/* Agent2API 词典构建产物：pt-BR/settings —— 由 desktop-tauri/i18n/build.mjs 生成，请勿手改；源头是 i18n-src/*.json */
window.wbI18nDict = window.wbI18nDict || {}; Object.assign(window.wbI18nDict, { " (a text copy is saved, {n} lines; takes effect after switching to \"Replace / Append\")": " (há um texto salvo, {n} linhas; passa a valer ao mudar para “Substituir / Anexar”)", " (all defaults)": " (todos com valores padrão)", " (file: {path})": " (arquivo: {path})", " (this is the active copy, {n} lines)": " (esta é a versão em vigor, {n} linhas)", " ({n} groups hidden)": " ({n} grupos ocultos)", " ({n} lines)": " ({n} linhas)", " ({n} overridden)": " ({n} itens sobrescritos)", " Continue?": "Confirmar e continuar?", " Text edited: {edited} (the remaining blocks use the official text).": " Texto alterado: {edited} (os demais blocos usam o texto oficial).", " before enabling this (if you have already registered, this step is skipped and the change takes effect directly).": " (se já estiver registrado, esta etapa é ignorada e a ativação é imediata).", " to {file}": " para {file}", " with the selected backup file, including the admin re-login after restore.": " pelo arquivo de backup selecionado, inclusive o novo login no painel após a restauração.", "\"Settings\" cannot be hidden (you would have to clear storage to get it back)": "\"Configurações\" não pode ser ocultado (seria preciso limpar o armazenamento para recuperá-lo)", "\"Settings\" is pinned, so its group cannot be hidden as a whole; you can still hide its other menus individually": "\"Configurações\" é fixo, então o grupo dele não pode ser ocultado inteiro; os outros menus podem ser ocultados individualmente", "\"{label}\" gateway-provided prompt restored to the official text": "O system prompt interno do gateway de “{label}” foi revertido para o texto oficial", "\"{label}\" gateway-provided prompt text updated": "Texto do system prompt interno do gateway de “{label}” atualizado", "\"{label}\" mode changed to \"{mode}\"": "Modo de “{label}” alterado para “{mode}”", "\"{label}\" now uses the built-in default prompt": "“{label}” agora usa o system prompt padrão integrado", "\"{label}\" prompt file updated": "Arquivo de prompt de “{label}” atualizado", "\"{label}\" prompt text updated": "Texto do prompt de “{label}” atualizado", "\"{label}\" will change from {previous} days to {days} days.": "“{label}” passará de {previous} para {days} dias.", "\"{label}\" will change from {previous} to {count} records.": "“{label}” passará de {previous} para {count} registros.", "(edited)": " (alterado)", "(no id)": "(sem id)", "(not in effect)": "(sem efeito)", "(official text)": " (texto oficial)", ", and it can be used to sign in directly. Keep it safe; do not share it or upload it to a public location.": ", e pode ser usado diretamente para login. Guarde-o com cuidado; não o compartilhe nem o envie para locais públicos.", ", custom providers: {added} added, {updated} updated": ", provedores personalizados: {added} adicionados, {updated} atualizados", ", plus any proxy credentials that may exist in the proxy pool / subscriptions. Use private storage only you can access; the account key is encrypted separately with the sync password, so leaking the storage alone does not expose your accounts.": ", além de eventuais credenciais de proxy no pool de proxies / assinaturas. Use armazenamento privado acessível apenas por você; a chave da conta é criptografada separadamente com a senha de sincronização, então vazar o armazenamento não expõe suas contas.", ", the pre-replace data was backed up as {name}": ", os dados pré-substituição foram backupados como {name}", ", {items}": ", {items}", ", {n} custom providers": ", {n} provedores personalizados", ", {time}": ", {time}", ". Event logs, request details, debug payloads and panel login state stay untouched. The current business data is backed up to backups/ under the config directory before replacing.": ". Logs de eventos, detalhes de requisições, pacotes de depuração e o estado de login do painel permanecem intactos. Os dados de negócio atuais são copiados para backups/ no diretório de configuração antes da substituição.", "/v1 rejects keyless requests": "/v1 rejeita requisições sem chave", "0 B": "0 B", "00:00 the next day": "00:00 do dia seguinte", "100% (default)": "100% (padrão)", "; later changes to the file will not take effect until this is cleared": ", e alterações posteriores no arquivo deixam de valer até que este campo seja limpo", "; rules do not run while masking is disabled": "; as regras não são executadas quando o mascaramento está desativado", "; the web admin panel is also open (open the same address in a browser)": "; o painel de administração web também está aberto (acesse pelo mesmo endereço no navegador)", "<local IP>": "<IP local>", "A model that cannot read images has only two options: let another model read the image for it, or hand the whole request to a model that can. Anything not covered here — including models that already read images — passes through untouched. Each request uses exactly one of the two ways; they are never chained, and a failure does not fall back to the other. Changes take effect immediately; there is nothing to save.": "Um modelo que não consegue ler imagens tem apenas duas saídas: deixar outro modelo ler a imagem por ele, ou entregar a requisição inteira a um modelo que consiga. O que não estiver aqui — inclusive modelos que já leem imagens — passa sem alteração. Cada requisição usa apenas uma das duas formas; elas nunca se encadeiam e uma falha não cai na outra. As mudanças aqui valem na hora; não há nada a salvar.", "A model that cannot read images has only two options: let another model read the image for it, or hand the whole request to a model that can. Choose the models and the vision model in the two blocks below. Anything not covered here — including models that already read images — passes through untouched. Changes here take effect immediately; there is nothing to save.": "Um modelo que não consegue ler imagens tem apenas duas saídas: deixar outro modelo ler a imagem por ele, ou entregar a requisição inteira a um modelo que consiga. Escolha os modelos e o modelo de visão nos dois blocos abaixo. O que não estiver aqui — inclusive modelos que já leem imagens — passa sem alteração. As mudanças aqui valem na hora; não há nada a salvar.", "A new feature or improvement you would like to see": "Funcionalidades novas ou melhorias que você gostaria de ver", "A new provider or model you would like supported": "Quero integrar um novo provedor ou modelo", "A panel administrator must be registered before enabling this; existing administrators skip this step. Management endpoints require an admin session or gateway key. API calls require an enabled gateway key; a default key is created automatically if none is available.": "É necessário registrar um administrador do painel antes de ativar. Se já houver um, esta etapa será ignorada. A API de gerenciamento exige uma sessão de administrador ou chave do gateway. Chamadas à API exigem uma chave do gateway ativa; se não houver nenhuma, uma chave padrão será criada automaticamente.", "A panel served by the same gateway; full management lives on desktop": "Painel servido pelo próprio gateway; o gerenciamento completo fica no desktop", "A snapshot already exists on the remote and will be overwritten": "Já existe um snapshot no remoto e ele será sobrescrito", "A vision model reads the images first, then the original model analyzes and answers.": "Um modelo de visão lê as imagens primeiro; depois, o modelo original analisa e responde.", "ALTCHA (local verification)": "ALTCHA (verificação local)", "Accept caller origin declarations": "Aceitar declarações de origem do solicitante", "Access": "Acesso", "Access Key ID": "Access Key ID", "Account": "Conta", "Account Import / Export": "Importar / exportar contas", "Account list": "Lista de contas", "Account routing": "Roteamento de contas", "Account-Switch Retries": "Retries trocando de conta", "Accounts, event logs, request records, debug payloads, and settings are stored in agent2api.db. Encryption keys are stored separately. To move between machines, use Full database backup / restore rather than copying only the database. To change the directory, set AGENT2API_PROXY_HOME and restart.": "Contas, logs, requisições, dados de depuração e configurações ficam no agent2api.db. As chaves ficam separadas. Para transferir dados entre máquinas, use Backup / restauração do banco inteiro, em vez de copiar só o banco. Para mudar o diretório, defina AGENT2API_PROXY_HOME e reinicie.", "Add Custom Header": "Adicionar cabeçalho personalizado", "Add Provider": "Adicionar provedor", "Add a provider to configure individually": "Adicionar provedor para configurar individualmente", "Add as backup": "Adicionar como alternativo", "Add fallback model": "Adicionar modelo alternativo", "Add masking rule": "Adicionar regra de mascaramento", "Add phase markers to Codex responses so reasoning and commands collapse after the answer, like official models": "Adicionar marcadores de fase às respostas do Codex para recolher o raciocínio e os comandos após a resposta, como nos modelos oficiais", "Add provider…": "Adicionar provedor…", "Add rule": "Adicionar regra", "Add to Home Screen": "Adicionar à tela inicial", "Add, edit, delete, enable, disable and reorder rules. An empty replacement deletes matched text. Restoring defaults resets only the rules, not the switch or provider scope.": "Adicione, edite, exclua, ative, desative e reordene regras. A substituição vazia exclui o texto correspondente. Restaurar o padrão redefine apenas as regras, sem alterar o interruptor nem o escopo de provedores.", "Admin account": "Conta de administrador", "Admin registered": "Administrador registrado", "Advanced settings": "Configurações avançadas", "Agent2API Mobile": "Agent2API Mobile", "Alibaba Cloud OSS": "Alibaba Cloud OSS", "All configured": "Tudo já configurado", "All data (accounts, event logs, request records, debug payloads, and settings) is kept in a single SQLite database, agent2api.db, in the configuration directory. To back up, just copy this file; to change its location, set the AGENT2API_PROXY_HOME environment variable and restart the app.": "Todos os dados (contas, logs de eventos, registros de requisições, payloads de debug e configurações) ficam em um único banco de dados SQLite, o agent2api.db, no diretório de configuração. Para fazer backup, basta copiar esse arquivo; para mudar o local de armazenamento, defina a variável de ambiente AGENT2API_PROXY_HOME e reinicie o programa.", "All data on this machine (accounts, gateway config, log stats, and desktop settings) will be ": "Todos os dados desta máquina (contas, configuração do gateway, estatísticas de logs e configurações do desktop) serão ", "All local database data will be replaced. A safety backup is saved first, and you must sign in again afterward. Existing local keys will not be overwritten.": "Todos os dados do banco local serão substituídos pelo backup. Um backup de segurança é salvo antes, e será preciso entrar novamente. As chaves locais existentes não serão sobrescritas.", "All roles": "Todos os papéis", "All roles keeps the existing behavior, including reasoning content and tool arguments. Selected roles rewrites only message content; unselected roles, reasoning content and tool arguments remain unchanged.": "Todos os papéis mantém o comportamento existente, incluindo o raciocínio e os argumentos de ferramentas. Com papéis selecionados, apenas o conteúdo das mensagens é alterado; papéis não selecionados, raciocínio e argumentos de ferramentas permanecem intactos.", "All three blocks are currently the official text.": "No momento, os três blocos estão com o texto oficial.", "Allow devices on the LAN to access the gateway": "Permitir que dispositivos na LAN acessem o gateway", "Allow other devices to access the gateway": "Permitir que outros dispositivos acessem o gateway", "Allow pages in a browser to call the gateway cross-origin (/v1/*)": "Permitir que páginas do navegador chamem o gateway de outra origem (/v1/*)", "Allow running without keys": "Permitir execução sem chaves", "Allowed hostnames": "Hostnames permitidos", "Allowed range: 5–120 seconds, also limited by the original request timeout. Oversized images, invalid formats and download failures are not treated as missing image support.": "Intervalo permitido: 5–120 segundos, limitado também pelo tempo da solicitação original. Imagens grandes, formatos inválidos e falhas de download não são tratados como falta de suporte a imagens.", "Also expose the web admin panel": "Também abrir o painel de administração web", "An account that fails to forward rests for a while before coming back: starting at 15 minutes, doubling per consecutive failure, capped at 1 hour; one success restores it immediately. The point is to let a failure cool off instead of hammering the same bad account request after request.": "Uma conta que falha no encaminhamento descansa um pouco antes de voltar: começa em 15 minutos, dobra a cada falha consecutiva, com teto de 1 hora; um único sucesso a restaura na hora. A ideia é deixar a falha esfriar em vez de martelar a mesma conta ruim requisição após requisição.", "An account with quota left that gets 429'd goes to the back of the queue and returns automatically after 30 minutes (one successful forward also brings it right back). This marks \"the shared pool is probably being drained by someone else\", not \"this account is broken\". ⚠️ Mind the interplay with the routing strategy: under \"Per-provider rotation\", the back of the queue means the whole provider gets pushed back — if one provider's accounts are rate-limited en masse, they all sink to the back and that provider may not be reached for a long time. Turn this off in that case, so 429'd accounts are only bound by cooldown (they come back automatically when it expires).": "Uma conta com cota que recebe 429 vai para o fim da fila e volta automaticamente após 30 minutos (um encaminhamento bem-sucedido também a traz de volta na hora). Isso sinaliza \"provavelmente o pool compartilhado está sendo drenado por outro\", e não \"esta conta está com problema\". ⚠️ Atenção à interação com a estratégia de roteamento: no \"Rodízio por provedor\", o fim da fila significa que o provedor inteiro é empurrado para trás — se as contas de um provedor forem limitadas em massa, todas afundam para o fim e aquele provedor pode não ser alcançado por muito tempo. Nesse caso desligue isto, deixando as contas 429 sujeitas só ao cooldown (elas voltam sozinhas quando ele expira).", "An available vision model inside the current route is preferred; if there is none, {model} answers directly instead of the original model.": "Prefere um modelo de visão disponível na rota atual; se não houver, {model} responde direto no lugar do modelo original.", "Android app (APK)": "Aplicativo Android (APK)", "Answering cross-origin requests: browsers can reach /v1/* directly cross-origin.": "Respondendo a requisições de outra origem: requisições de navegador com CORS podem se conectar diretamente a /v1/*.", "App status": "Status do app", "App version: {version}": "Versão do app: {version}", "App window": "Janela do aplicativo", "App-specific password": "Senha de aplicativo", "Appearance": "Aparência", "Appearance · Access · About": "Aparência · Acesso · Sobre", "Append": "Anexar", "Append gateway prompt": "Anexar prompt do gateway", "Applied": "Aplicado", "Applies only to queueing upstreams : when a model is busy the upstream raises no error, it just replies \"suggest waiting N seconds\"; the gateway waits for the suggested duration and resends the same request, and only when the wait count is exhausted is \"queueing\" returned as an error (HTTP 503, with text explaining that this is not a sign-in or quota problem). The wait happens before the first byte and comes out of the \"Response Headers Timeout\" budget — together the two settings determine how long one request can stall at most; queueing does not mark the account as rate-limited and does not switch accounts (everyone is queueing). Takes effect on the next request after saving, no restart needed.": "Só tem efeito em upstreams com “sistema de fila” : quando o modelo está ocupado, o upstream não retorna erro, apenas responde “recomendamos voltar em N segundos”; o gateway espera o tempo sugerido e reenvia a mesma requisição, e só quando o número de esperas se esgota a “fila” é devolvida como erro (HTTP 503, com um texto explicando que não é um problema de login nem de cota). A espera acontece antes do primeiro byte e consome o orçamento do “Timeout de espera de resposta” — as duas configurações, juntas, determinam quanto tempo no máximo uma requisição pode ficar travada; a fila não marca a conta como limitada nem troca de conta (todos estão igualmente na fila). Passa a valer para a próxima requisição após salvar, sem reiniciar.", "Applies to all providers by default, including plugins and custom providers added later. With a selected scope, other providers are not masked. Clearing the selection returns to all providers.": "Aplica-se a todos os provedores por padrão, incluindo plugins e provedores personalizados adicionados depois. Ao selecionar um escopo, os outros provedores não são mascarados. Limpar a seleção volta a todos os provedores.", "Apply the selected mode directly": "Aplicar diretamente o modo selecionado", "Apply the settings above right away": "Aplicar as configurações acima direto", "Apply to providers": "Aplicar aos provedores", "Architecture": "Arquitetura", "Assigned client": "Cliente atribuído", "Assisted image reading": "Leitura assistida de imagens", "Assisted image reading settings": "Configuração de leitura assistida", "Assisted reading keeps the original answering model; switching lets the vision model answer directly. This consent also covers your per-model overrides.": "A leitura assistida mantém o modelo original para responder; a troca permite que o modelo de visão responda diretamente. Esta autorização também inclui as configurações por modelo.", "Assisted reading or vision model switching, off by default": "Leitura assistida ou troca de modelo de visão, desativada por padrão", "Assisted reading · Original model answers": "Leitura assistida · O modelo original responde", "At least 12 characters": "Ao menos 12 caracteres", "At least 8 characters; needed when restoring on another machine": "Pelo menos 8 caracteres; necessário ao restaurar em outra máquina", "At least one group must remain": "Pelo menos um grupo deve permanecer", "At most {max} status codes": "No máximo {max} status codes na lista", "Auto continuation": "Continuação automática", "Auto sync": "Sincronização automática", "Automatically switched to a minimal neutral prompt (upstream content blocking was hit, most likely a false positive on system fingerprints); it clears automatically at {until}. During this period this mode's own prompt is not sent; once you have fixed the prompt you can clear it immediately.": "Mudança automática para o system prompt neutro mínimo (houve bloqueio de conteúdo no upstream, provavelmente um falso positivo de fingerprint do system); o fallback será encerrado automaticamente em {until}. Durante esse período, o prompt próprio deste modo não é enviado; depois de corrigir o prompt, é possível encerrar o fallback imediatamente.", "Automatically upload after local account, configuration, check-in and balance record changes (changes within 1 second are merged, at most one upload every 10 seconds; no request is sent when nothing changed).": "Envia automaticamente após alterações locais em contas, configuração, check-in e registros de saldo (alterações em até 1 segundo são agrupadas, no máximo um envio a cada 10 segundos; nenhuma requisição é feita se nada mudou).", "Available vision models in the current route": "Modelos de visão disponíveis na rota atual", "Back up database": "Fazer backup do banco", "Backing up…": "Fazendo backup…", "Backup model": "Modelo alternativo", "Backup password": "Senha do backup", "Before forwarding, fingerprint masking applies rules in list order to message text, including conversation content, reasoning content and tool-call arguments. The default rules contain exact replacements and regular-expression deletions for client templates and billing headers. You can add, edit, delete, enable, disable and reorder rules; an empty replacement deletes the matched text. All providers are selected by default, or you can select specific providers. Only the outbound copy is modified; responses are unchanged. Click Save settings to apply changes to the next request. An empty rule list performs no fingerprint rewriting, and restoring defaults resets only the rules.": "Antes de encaminhar, o mascaramento aplica as regras na ordem da lista ao texto das mensagens, incluindo conversa, raciocínio e argumentos de chamadas de ferramentas. As regras padrão incluem substituições exatas e exclusões por expressão regular de modelos do cliente e cabeçalhos de cobrança. Você pode adicionar, editar, excluir, ativar, desativar e reordenar regras; uma substituição vazia exclui o texto correspondente. Por padrão, aplica-se a todos os provedores, ou você pode selecionar vários. Apenas a cópia enviada ao upstream é alterada; as respostas não mudam. Clique em Salvar configurações para aplicar à próxima requisição. Uma lista vazia não altera fingerprints, e restaurar o padrão redefine apenas as regras.", "Before the replace, the current data is automatically backed up to the backups/ folder under the config directory.": "Antes da substituição, os dados atuais são automaticamente backupados na pasta backups/ do diretório de configuração.", "Beta release": "Versão beta", "Block 1": "Primeiro bloco", "Block 1 (identity sentence)": "Primeiro bloco (frase de identidade)", "Block 2": "Segundo bloco", "Block 2 (stable block)": "Segundo bloco (estável)", "Block 3": "Terceiro bloco", "Block 3 (dynamic block)": "Terceiro bloco (dinâmico)", "Bot verification settings saved": "Configurações de verificação de bots salvas", "Brand logo": "Logo da marca", "Brand preview": "Prévia da marca", "Brand settings": "Configurações da marca", "Brand settings saved": "Configurações da marca salvas", "Brazilian Portuguese": "Português (Brasil)", "Browser / PWA": "Navegador / PWA", "Browser panel": "Painel no navegador", "Browser tab": "Aba do navegador", "Browsers only offer offline caching over https or localhost. Accessing over plain http on the LAN still works normally.": "Os navegadores só oferecem cache offline em https ou localhost. O acesso por http na LAN continua funcionando normalmente.", "Bucket": "Bucket", "Bug Report": "Relatar um problema", "Bugs, errors, or unexpected behavior": "Bugs, erros ou comportamentos anormais", "Built-in User-Agent rule": "Regra integrada de identificação", "Built-in defaults": "Padrões integrados", "Built-in identification, custom rules, and origin declarations": "Identificação integrada, regras personalizadas e declarações de origem", "Busy upstream models queue first (replying \"suggest waiting N seconds\"): the gateway waits a while and resends the same request, up to a set number of waits. Default 2; accepts 0–10. 0 means no waiting: a queued response returns 503 directly and states that this is not a sign-in or quota problem.": "Quando o modelo no upstream está ocupado, ele primeiro entra na fila (respondendo “recomendamos voltar em N segundos”): o gateway aguarda um pouco e reenvia a mesma requisição, até um número máximo de esperas. Padrão 2; valores aceitos 0–10; 0 significa não esperar — a fila retorna 503 diretamente, informando que “não é um problema de login nem de cota”.", "By default the gateway listens only on 127.0.0.1 and only this machine can reach it. Once enabled, the gateway listens on all network interfaces, and devices on the same LAN can point the API address at this machine's IP to share it. For security, you must first register a panel administrator: the admin API then requires an admin session or a gateway key, so model quotas are not left wide open to the LAN; and when no gateway key is enabled, the forwarding API refuses service too, until the first one is created. The change requires an app restart to take effect. \"Also serve the web admin panel\" exposes the admin UI to the LAN as well (other devices can open this machine's IP in a browser to manage it); it is off by default — the desktop build still serves the panel only from this app itself.": "Por padrão, o gateway escuta apenas 127.0.0.1 e só esta máquina tem acesso. Ao ativar, o gateway passa a escutar todas as interfaces de rede e dispositivos na mesma LAN podem usar a API apontando o endereço para o IP desta máquina. Por segurança, antes de ativar é obrigatório registrar um administrador do painel: a interface de administração passa a exigir sessão de administrador ou chave do gateway, e a cota dos modelos não fica exposta na LAN; quando não há nenhuma chave do gateway ativa, a interface de encaminhamento também recusa atendimento até que a primeira seja criada. A mudança exige reiniciar o aplicativo para ter efeito. “Também abrir o painel de administração web” disponibiliza a interface de administração na LAN (o navegador de outros dispositivos abre o IP desta máquina para gerenciar); desativado por padrão — o painel do desktop continua sendo servido apenas pelo próprio programa.", "By default, closing the window does not quit the app; it shrinks the window to the system tray and forwarding keeps running in the background (OpenAI clients are unaffected). To quit the app completely, right-click the tray icon and choose \"Exit\". With this switch off, clicking the close button quits the app and forwarding stops with it. With \"Launch at startup\" on, the app starts automatically when you sign in to the system (usually staying in the tray), so you do not need to open it manually.": "Por padrão, fechar a janela não encerra o programa: ela é recolhida para a bandeja do sistema e o encaminhamento continua rodando em segundo plano (clientes OpenAI não são afetados). Para encerrar o programa de vez, clique com o botão direito no ícone da bandeja e escolha “Sair”. Com este switch desativado, clicar no botão de fechar encerra o programa e o encaminhamento é interrompido. Com “Iniciar com o sistema” ativado, o programa inicia automaticamente ao entrar no sistema (normalmente já na bandeja), sem precisar abri-lo manualmente.", "By default, only this machine can connect (127.0.0.1). Enabling this listens on all IPv4 interfaces (0.0.0.0); access depends on your network and firewall, is not limited to the LAN, and is not automatically opened to the internet. A panel administrator must be registered first. Management endpoints require an admin session or gateway key; API calls require an enabled gateway key, with a default key created automatically if needed. The web management panel is off by default. Enable it to sign in from another device's browser; disabling it does not affect API forwarding or local desktop management. Either switch requires an app restart.": "Por padrão, somente esta máquina pode acessar (127.0.0.1). Ao ativar, o gateway escuta em todas as interfaces IPv4 (0.0.0.0); o acesso depende da rede e do firewall, não se limita à rede local e não é aberto automaticamente à internet. É necessário registrar um administrador do painel antes. A API de gerenciamento exige uma sessão de administrador ou chave do gateway; chamadas à API exigem uma chave ativa, criada automaticamente como padrão se necessário. O painel web fica desativado por padrão. Ative-o para entrar pelo navegador de outro dispositivo; desativá-lo não afeta o encaminhamento da API nem o gerenciamento desktop local. Alterar qualquer uma das opções exige reiniciar o aplicativo.", "CORS": "CORS", "Caller declaration": "Declaração do solicitante", "Caller declarations are disabled, so this rule will not apply. Enable them in client identification settings first.": "As declarações de origem estão desativadas; esta regra não será aplicada. Ative-as nas configurações de identificação.", "Cannot reach this gateway. Check the address and port, that the gateway is running, and that \"LAN access\" is enabled; for https also check that the certificate is valid.": "Não foi possível alcançar este gateway. Confira o endereço e a porta, se o gateway está rodando e se o \"Acesso pela rede local\" está ativo; no caso de https, confira também se o certificado é válido.", "Cannot reach this gateway. Check the address, port, and firewall settings, and make sure the gateway is running. For the desktop app, enable Allow other devices to access the gateway under Settings → Gateway → Network access. For HTTPS, also check that the certificate is valid.": "Não foi possível alcançar este gateway. Verifique o endereço, a porta, o firewall e se o gateway está em execução. No aplicativo desktop, ative Permitir que outros dispositivos acessem o gateway em Configurações → Gateway → Acesso pela rede. Para HTTPS, verifique também se o certificado é válido.", "Captcha": "Captcha", "Captcha token pool": "Pool de tokens de captcha", "Captcha token pool settings refreshed": "Configurações do pool de tokens de captcha atualizadas", "Change Web Admin Panel": "Alterar o painel de administração web", "Change password": "Alterar senha", "Changing the password requires the current one. After success, sign-ins on other devices and browsers are revoked immediately; this session stays active.": "Alterar a senha exige a senha atual. Após o sucesso, os acessos em outros dispositivos e navegadores são revogados imediatamente; esta sessão permanece ativa.", "Changing…": "Alterando…", "Checking…": "Verificando…", "Choose a backup file and restore": "Escolher um arquivo de backup e restaurar", "Choose a separate vision model": "Escolher um modelo de visão separado", "Choose location and encrypt backup": "Escolher local e criptografar backup", "Choose which menus the sidebar shows, in what order, and how they are grouped. Hiding only affects navigation — it does not revoke access, and hidden pages can still be opened by URL.": "Define quais menus a barra lateral mostra, em que ordem e como são agrupados. Ocultar afeta apenas a navegação — não revoga acesso, e páginas ocultas continuam abrindo pela URL.", "Clear Now": "Encerrar agora", "Clear Text Here": "Limpar o texto deste campo", "Clear local credentials": "Limpar credenciais locais", "Cleared the UI-edited prompt (falls back to the file / built-in default)": "Prompt editado na interface removido (volta para o arquivo / padrão integrado)", "Cleared the UI-edited text for \"{label}\"": "Texto editado na interface de “{label}” removido", "Click to rename": "Clique para renomear", "Client identification": "Identificação de clientes", "Client identification is not ready. Refresh the page and try again.": "A identificação de clientes ainda não está pronta. Atualize a página e tente novamente.", "Client name": "Nome do cliente", "Client name is duplicated or conflicts with a built-in name": "Nome de cliente duplicado ou em conflito com um nome integrado", "Client-specific header": "Cabeçalho específico do cliente", "Clients (CLI tools such as Claude Code / Codex) inject dozens of fixed template sentences into the system prompt, and the upstream reviews them by word-for-word matching — a hit blocks the whole request (HTTP 400). Fingerprint masking can rewrite the sentences observed to be hit, but a different client version may introduce new ones. Here you can replace the whole system prompt with the gateway's own one: (1) \"Passthrough\" = leave the client's system prompt untouched (the default, identical to the previous behavior); (2) \"Replace\" = delete all client system / developer messages and substitute the gateway's prompt (the client's project instructions disappear with them); (3) \"Append\" = insert one gateway prompt after the leading consecutive system blocks, leaving existing messages word-for-word intact (the client's instructions and the gateway prompt are used together). That prompt has two sources: a prompt file (leave empty for the built-in default), or editing the text right in the UI — an edited text takes precedence (over the file), and clearing it goes back to the file / built-in default. Also, in Passthrough / Append mode, if content blocking is hit (usually a fingerprint false positive), the gateway automatically retries once with a minimal neutral prompt and extends the \"fallback period\" to 00:00 the next day — during that period every request goes out with the neutral prompt directly, with no 400 hit first; you can see it here and clear it early. The items above are **defaults**: to configure a single provider, add a row under \"Per-Provider Configuration\" below (providers with \"Gateway-Provided Prompt\" are listed there by default) — different upstreams tolerate these differently.": "Os clientes (ferramentas CLI como Claude Code / Codex) injetam dezenas de frases de template fixas no system prompt, e o upstream as revisa por correspondência palavra por palavra: um acerto bloqueia a requisição inteira (HTTP 400). O mascaramento de fingerprint consegue reescrever as frases que foram bloqueadas nos testes, mas uma versão diferente do cliente pode trazer novas. Aqui é possível substituir o system inteiro pelo do próprio gateway: ① “Passthrough” = não mexe no system do cliente (padrão, comportamento idêntico ao anterior); ② “Substituir” = apaga todas as mensagens system / developer do cliente e coloca o prompt do gateway (as instruções de projeto do cliente desaparecem junto); ③ “Anexar” = insere um prompt do gateway depois dos blocos system consecutivos do início, deixando as mensagens existentes palavra por palavra intactas (as instruções do cliente e o prompt do gateway são usados juntos). Esse prompt tem duas origens: o arquivo de prompt (deixe vazio para usar o padrão integrado) ou a edição direta do texto na interface — se editado, vale o texto editado (com prioridade sobre o arquivo); se limpo, volta para o arquivo / padrão integrado. Além disso, nos modos Passthrough / Anexar, quando há bloqueio de conteúdo (geralmente um falso positivo de fingerprint), o gateway tenta de novo automaticamente com um system prompt neutro mínimo e estende o “período de fallback” até 00:00 do dia seguinte — nesse período, todas as requisições saem direto com o prompt neutro, sem bater primeiro em um 400; aqui você pode ver e encerrar o fallback antecipadamente. Os itens acima são **valores padrão**: para configurar um provedor específico, adicione uma linha em “Por provedor” abaixo (os provedores com “Interno do gateway” já aparecem lá por padrão) — cada upstream tolera esses conteúdos de forma diferente.", "Cline Spoofed Headers": "Cabeçalhos spoofed do Cline", "Cline spoofed headers refreshed": "Cabeçalhos spoofed do Cline atualizados", "Close & Restart": "Desativar e reiniciar", "Closing the window does not quit the app; forwarding keeps running in the background. To quit, use the tray menu": "Fechar a janela não encerra o programa; o encaminhamento continua rodando em segundo plano. Para sair, use o menu da bandeja", "Closing the window quits the app, and background forwarding stops with it": "Fechar a janela encerra o programa e o encaminhamento em segundo plano é interrompido", "Cloud sync": "Sincronização na nuvem", "Collapse third-party model work after the answer": "Recolher automaticamente o trabalho de modelos de terceiros após a resposta", "Collapse third-party model work after the answer disabled": "Recolhimento automático do trabalho de modelos de terceiros após a resposta desativado", "Community & support": "Comunidade e suporte", "Compress large inline images in conversations before forwarding (only the copy sent upstream changes; image generation and editing are unaffected)": "Comprimir imagens embutidas grandes nas conversas antes de encaminhar (só a cópia enviada ao provedor muda; geração e edição de imagens não são afetadas)", "Confirm": "Confirmar", "Confirm Shorter Retention": "Confirmar a redução dos dias de retenção", "Confirm adds the rule to the draft. Click Save settings to apply it.": "Confirmar adiciona a regra ao rascunho. Clique em Salvar configurações para aplicá-la.", "Confirm and save": "Confirmar e salvar", "Confirm backup password": "Confirmar senha do backup", "Confirm image processing consent": "Confirmar autorização para processar imagens", "Confirm new password": "Confirmar nova senha", "Confirm reduced data retention": "Confirmar redução da retenção de dados", "Confirm upload": "Confirmar envio", "Conflicting client identifiers": "Identificadores de clientes conflitantes", "Connect Timeout": "Timeout de conexão", "Connection failed: {message}": "Falha na conexão: {message}", "Contains": "Contém", "Contains the pinned \"Settings\" menu, so the group cannot be hidden as a whole (you can still hide its other menus individually)": "Contém o item fixo \"Configurações\", então o grupo não pode ser ocultado inteiro (os outros menus podem ser ocultados individualmente)", "Content-block fallback": "Fallback de bloqueio de conteúdo", "Continue & Clean Up": "Continuar e limpar", "Controls how Token counts are written in reports and request logs: when on, values are shown with 万 / 亿-style local magnitude words (万 / 亿 in Simplified Chinese, 萬 / 億 in Traditional Chinese, 万 / 億 in Japanese, 만 / 억 in Korean); when off, k / M abbreviations are used (matching how upstream docs and API fields write them). For English / Portuguese the local magnitude words are k / M, so this makes no difference to them. This only affects how values are displayed; no statistics or stored numbers change.": "Controla como o Token é exibido no relatório e nos logs de requisições: quando ativado, exibe com magnitudes locais no estilo “k / M” (chinês simplificado: 万 / 亿; chinês tradicional: 萬 / 億; japonês: 万 / 億; coreano: 만 / 억); quando desativado, usa abreviações k / M (igual à forma usada na documentação e nos campos da API do upstream). Para inglês e português, as magnitudes locais são exatamente k / M, então esta opção não faz diferença para eles. Afeta apenas a forma de exibição; não altera nenhum valor de estatística ou de armazenamento.", "Controls how token counts read in reports and request logs: on shows Chinese magnitudes (1.2亿 / 8400万), off uses k / M / B abbreviations (consistent with upstream docs and API fields). This only changes the display; no statistics or stored numbers are affected.": "Controla como as contagens de token aparecem nos relatórios e no log de requisições: ativado mostra magnitudes chinesas (1.2亿 / 8400万), desativado usa abreviações k / M / B (iguais às dos documentos e campos de API do upstream). Isso altera apenas a exibição; nenhum número estatístico ou armazenado muda.", "Controls the UI's light / dark colors; it is the same setting as the three theme buttons at the bottom of the left sidebar (change either one and the other follows immediately). \"System\" switches automatically with the operating system's current light / dark setting and follows changes as they happen; choosing \"Light\" or \"Dark\" pins the UI to that mode regardless of the system. The window title bar's light / dark color stays in sync too, so you never end up with a dark UI under a light title bar.": "Controla o tema claro / escuro da interface; é a mesma configuração dos três botões de tema no rodapé da barra lateral esquerda (mudar em um lugar reflete imediatamente no outro). “Sistema” acompanha automaticamente o tema claro / escuro atual do sistema operacional e reage na hora a mudanças no tema do sistema; escolher “Claro” ou “Escuro” fixa a interface nesse modo, sem seguir o sistema. A barra de título da janela acompanha junto, então não ocorre de a interface ficar escura com uma barra de título clara.", "Convert developer-role messages to system before forwarding, for OpenAI-compatible upstreams that do not support the developer role": "Converte mensagens com papel developer para system antes do encaminhamento, para upstreams compatíveis com OpenAI que não suportam o papel developer", "Copied all version info": "Todas as informações de versão foram copiadas", "Copy all info": "Copiar todas as informações", "Copy for your client": "Copiar para o cliente", "Copyright notice": "Aviso de copyright", "Could not load network access settings. Please try again later.": "Não foi possível carregar as configurações de acesso pela rede. Tente novamente mais tarde.", "Could not read account information, please try again later": "Não foi possível ler as informações da conta. Tente novamente mais tarde", "Could not read bot verification settings": "Não foi possível ler as configurações de verificação de bots", "Could not read brand settings": "Não foi possível ler as configurações da marca", "Could not read cloud sync settings. Please try again later.": "Não foi possível ler as configurações de sincronização na nuvem. Tente novamente mais tarde.", "Could not read the Cline spoofed header settings. Please try again later.": "Não foi possível ler as configurações de cabeçalhos spoofed do Cline; tente novamente mais tarde", "Could not read the current value of \"{label}\". Setting it to {count} records may delete excess historical data.": "Não foi possível ler o valor atual de “{label}”. Definir {count} registros pode excluir os dados históricos excedentes.", "Could not read the current value of \"{label}\"; changing it to {days} days may delete excess historical data.": "Não foi possível ler o valor atual de “{label}”; mudar para {days} dias pode excluir dados históricos excedentes.", "Could not read the debug mode settings. Please try again later.": "Não foi possível ler as configurações do modo debug; tente novamente mais tarde", "Could not read the developer role compatibility setting, please try again later": "Não foi possível ler a configuração de compatibilidade com papel developer, tente novamente mais tarde", "Could not read the fingerprint masking settings. Please try again later.": "Não foi possível ler as configurações de mascaramento de fingerprint; tente novamente mais tarde", "Could not read the gateway CORS settings. Please try again later.": "Não foi possível ler as configurações de CORS do gateway; tente novamente mais tarde", "Could not read the image. Select it again.": "Não foi possível ler a imagem. Selecione-a novamente.", "Could not read the models.dev metadata state. Please try again later.": "Não foi possível ler o estado dos metadados do models.dev. Tente novamente mais tarde.", "Could not read the saved fingerprint masking settings": "Não foi possível ler as configurações de mascaramento salvas", "Could not read the system prompt settings. Please try again later.": "Não foi possível ler as configurações do system prompt; tente novamente mais tarde", "Could not read the third-party reasoning collapse setting, please try again later": "Não foi possível ler a configuração de recolhimento do trabalho de modelos de terceiros; tente novamente mais tarde", "Counts": "Contagens", "Create a Turnstile widget in Cloudflare first. Managed mode is recommended. Add the actual domain names used to access the panel.": "Primeiro crie um widget Turnstile na Cloudflare. Recomendamos o modo Managed. Adicione os domínios usados para acessar o painel.", "Created at: {time}": "Criado em: {time}", "Created group \"{name}\" — use ＋ on its header to move menus in": "Grupo \"{name}\" criado — use ＋ no cabeçalho para mover menus", "Credential request headers have been redacted.": "Os cabeçalhos de requisição com credenciais foram mascarados.", "Credentials are stored only on this phone, separately for each server": "As credenciais ficam apenas neste celular, separadas por servidor", "Current interface": "Interface atual", "Current password": "Senha atual", "Current sample result: {name}": "Resultado da amostra atual: {name}", "Current settings are saved": "As configurações atuais estão salvas", "Currently displayed at 100% (the default).": "Exibindo no momento a 100% (proporção padrão).", "Currently displayed at {n}%.": "Exibindo no momento a {n}%.", "Currently fixed to Dark mode; it does not follow the system.": "No momento, fixo no modo escuro, sem seguir o sistema.", "Currently fixed to Light mode; it does not follow the system.": "No momento, fixo no modo claro, sem seguir o sistema.", "Currently following the operating system's light / dark setting; the UI follows along automatically when the system switches.": "No momento, seguindo o tema claro / escuro do sistema operacional; quando o sistema mudar, a interface acompanha automaticamente.", "Currently in Passthrough mode: saving it will not send it; it takes effect only after switching to \"Replace / Append\".": "No momento, o modo é Passthrough: mesmo salvando, o texto não é enviado; só passa a valer após mudar para “Substituir / Anexar”.", "Currently in use": "Em uso", "Currently shown as \"1.2亿 / 8400万\"-style Chinese magnitudes.": "Atualmente exibido como magnitudes chinesas no estilo \"1.2亿 / 8400万\".", "Currently shown with k / M / B abbreviations (e.g. 1.20M / 8.4k / 1.2B).": "Exibindo no momento com abreviações k / M / B (ex.: 1.20M / 8.4k / 1.2B).", "Currently shown with k / M abbreviations (e.g. 1.20M / 8.4k).": "Exibindo no momento com abreviações k / M (ex.: 1.20M / 8.4k).", "Currently shown with 万 / 亿-style local magnitude words (e.g. 1.2亿 / 8400万).": "Exibindo no momento com magnitudes locais no estilo k / M (ex.: 120M / 84M).", "Currently unavailable": "Indisponível no momento", "Custom User-Agent": "User-Agent personalizado", "Custom client categories": "Categorias de clientes personalizadas", "Custom client limit reached": "Limite de clientes personalizados atingido", "Custom identification rules": "Regras de identificação personalizadas", "Custom provider {id}": "Provedor personalizado {id}", "Customize the name and logo displayed on the website and in the application.": "Personalize o nome e o logo exibidos no site e na interface do aplicativo.", "Customized": "Personalizado", "Daily aggregate retention (days)": "Retenção dos agregados diários (dias)", "Data": "Dados", "Data Retention": "Retenção de dados", "Data Storage": "Armazenamento de dados", "Data directory": "Diretório de dados", "Data is kept in agent2api.db in the configuration directory; to change the location, set the AGENT2API_PROXY_HOME environment variable and restart the app.": "Os dados ficam todos em agent2api.db, no diretório de configuração; para mudar de local, defina a variável de ambiente AGENT2API_PROXY_HOME e reinicie o programa.", "Data retention settings refreshed": "Configurações de retenção de dados atualizadas", "Database file": "Arquivo do banco", "Database schema": "Schema do banco", "Database unavailable": "Banco de dados indisponível", "Days": "Dias", "Debug Payloads": "Payloads de debug", "Debug build": "Build de desenvolvimento", "Debug mode": "Modo de depuração", "Debug mode settings refreshed": "Configurações do modo debug atualizadas", "Defaults to 1,000,000 records. The oldest excess request records and their raw bodies are removed without affecting daily aggregate reports; retention days also apply.": "Padrão de 1.000.000 de registros. Os registros excedentes mais antigos e seus corpos originais são removidos sem afetar os relatórios agregados diários; os dias de retenção também se aplicam.", "Defaults to 10,000 records, with capacity allocated by log level. The oldest excess records are removed; retention days also apply.": "Padrão de 10.000 registros, com capacidade distribuída por nível de log. Os registros excedentes mais antigos são removidos; os dias de retenção também se aplicam.", "Defaults to 5 minutes. Changes during the interval are merged into the latest snapshot and uploaded when it is due. Manual uploads are not limited. Failed attempts are retried automatically with a longer delay.": "O padrão é 5 minutos. As alterações durante o intervalo são reunidas no snapshot mais recente e enviadas ao final da espera. Uploads manuais não são limitados. Em caso de falha, o sistema aumenta a espera e tenta novamente automaticamente.", "Delete client category": "Excluir categoria de cliente", "Delete group": "Excluir grupo", "Delete group \"{name}\"? Its {n} menus will move to \"{target}\" — nothing is lost.": "Excluir o grupo \"{name}\"? Os {n} menus vão para \"{target}\" — nada é perdido.", "Delete identification rule": "Excluir regra de identificação", "Delete matched text": "Excluir texto correspondente", "Delete status code {code}": "Remover o status code {code}", "Delete the empty group \"{name}\"?": "Excluir o grupo vazio \"{name}\"?", "Delete this group (its menus move to the first group)": "Excluir este grupo (os menus vão para o primeiro grupo)", "Delete {code}": "Remover {code}", "Deleted group \"{name}\"": "Grupo \"{name}\" excluído", "Deployment": "Forma de execução", "Designated fallbacks remain subject to the current permissions and route scope. Route-group requests never leave the group. This mode never falls back to assisted image reading.": "As alternativas continuam sujeitas às permissões e à rota atuais. Solicitações de um grupo nunca saem dele. Este modo nunca muda para leitura assistida de imagens.", "Desktop app": "Aplicativo desktop", "Desktop runtime unavailable; cannot save right now": "Runtime do desktop indisponível; não é possível salvar agora", "Desktop sign-in / registration verification": "Verificação de login / cadastro no desktop", "Desktop: sign-in / registration requires ALTCHA proof-of-work": "Desktop: login / registro exige verificação ALTCHA", "Desktop: sign-in / registration requires ALTCHA proof-of-work (in use now)": "Desktop: login / registro exige verificação ALTCHA (em uso agora)", "Developer role compat": "Compatibilidade de papel developer", "Developer role compatibility disabled": "Compatibilidade com papel developer desativada", "Developer role compatibility setting refreshed": "Configuração de compatibilidade com papel developer atualizada", "Devices that can reach the gateway will be able to open the web management panel in a browser and sign in with an administrator account. Its access scope is the same as the gateway's and is not limited to the LAN.": "Dispositivos que conseguem alcançar o gateway poderão abrir o painel web no navegador e entrar com uma conta de administrador. O alcance de acesso é o mesmo do gateway e não se limita à rede local.", "Disable LAN Access": "Desativar acesso LAN", "Disable network access": "Desativar acesso pela rede", "Disable reasoning": "Desativar raciocínio", "Disabled": "Desativado", "Disabled. {note}": "Desativado. {note}", "Disabled: no extra phase markers; the client controls how work is displayed.": "Desativado: sem marcadores extras; o cliente controla a exibição do trabalho.", "Discard edits and refresh": "Descartar alterações e atualizar", "Display name": "Nome de exibição", "Do not adapt images": "Não adaptar imagens", "Docker container": "Contêiner Docker", "Download failed: {message}": "Falha no download: {message}", "Downstream bodies": "Corpos do downstream", "Drag group {name}": "Arrastar grupo {name}", "Drag menu {name}": "Arrastar menu {name}", "Drag the ⠿ handle to reorder (menus can move across groups); use the switches to show or hide; click a group name to rename it; the ＋ on a group header moves another menu into it; the eye button hides a whole group. Changes apply instantly and are remembered — the sidebar on the left is the result. Keyboard: focus a handle and press Alt+↑ / ↓.": "Arraste o ⠿ para reordenar (menus podem mudar de grupo); use os interruptores para mostrar ou ocultar; clique no nome do grupo para renomear; o ＋ no cabeçalho move outro menu para o grupo; o botão de olho oculta o grupo inteiro. As mudanças valem na hora e ficam salvas — a barra lateral à esquerda é o resultado. Teclado: foque a alça e pressione Alt+↑ / ↓.", "Drag to reorder groups (Alt+↑ / ↓ also works)": "Arraste para reordenar os grupos (Alt+↑ / ↓ também funciona)", "Drag to reorder, across groups too (Alt+↑ / ↓ also works)": "Arraste para reordenar, inclusive entre grupos (Alt+↑ / ↓ também funciona)", "Duration of each wait. Default 0 = follow the upstream's suggestion (measured 9–30 seconds; 15 seconds when the upstream gives none). Accepts 0–120 seconds to force a fixed duration.": "Duração de cada espera; padrão 0 = seguir a sugestão do upstream (medido: 9~30 segundos; quando o upstream não sugere nada, usa 15 segundos). Aceita 0–120 segundos para forçar uma duração fixa.", "Each request uses exactly one of the two ways; they are never chained and a failure does not fall back to the other. Whichever vision model is configured is the one that receives the images for that request.": "Cada requisição usa apenas uma das duas formas; elas nunca se encadeiam e uma falha não cai na outra. O modelo de visão configurado é quem recebe as imagens daquela requisição.", "Edit Gateway-Provided Prompt · {label}": "Editar o system prompt interno do gateway · {label}", "Edit Prompt Text · Global": "Editar o texto do prompt · Global", "Edit Prompt Text · {label}": "Editar o texto do prompt · {label}", "Edit Text": "Editar texto", "Edit identification rule": "Editar regra de identificação", "Edit masking rule": "Editar regra de mascaramento", "Edit the prompt text right here: after saving, this text takes precedence (over the prompt file above), and clearing it falls back to the file / built-in default. No need to open a file in an editor just to change one word.": "Edite o texto do prompt diretamente aqui: após salvar, este texto passa a valer (com prioridade sobre o arquivo de prompt acima); se você limpar, volta para o arquivo / padrão integrado. Não é preciso abrir um arquivo em um editor só para mudar uma palavra.", "Edited so far: {edited}.": "Editados no momento: {edited}.", "Effective value: {value}": "Valor em uso: {value}", "Empty = do not keep this copy; falls back to the prompt file / built-in default prompt.": "Vazio = não usar este texto e voltar para o arquivo de prompt / system prompt padrão integrado.", "Empty group · use ＋ on the header to move menus in": "Grupo vazio · use ＋ no cabeçalho para mover menus", "Enable LAN Access": "Ativar acesso LAN", "Enable cloud sync": "Ativar sincronização na nuvem", "Enable image compatibility": "Ativar compatibilidade de imagens", "Enable network access": "Ativar acesso pela rede", "Enable origin declarations": "Ativar declarações de origem", "Enable rule": "Ativar regra", "Enable rule: {name}": "Ativar regra: {name}", "Enabled": "Ativado", "Enabled by default. Only the role field changes — message content and order stay untouched; this only rewrites the copy sent upstream, and what the client sees never changes.": "Ativado por padrão. Só o campo role muda — conteúdo e ordem das mensagens ficam intactos; isto reescreve apenas a cópia enviada ao upstream, e o que o cliente vê nunca muda.", "Enabled for all providers by default. Edit rules or provider scope and click Save settings; the next request uses the changes without restarting. Rule hits are still recorded in the request log's masking tag.": "Ativado para todos os provedores por padrão. Edite as regras ou o escopo e clique em Salvar configurações; a próxima requisição usa as alterações sem reiniciar. As correspondências continuam registradas na etiqueta de mascaramento do log.", "Enabled plugins provide these options and defaults. Plugin updates do not replace your saved overrides.": "Os plugins ativados fornecem estas opções e valores padrão. Atualizações do plugin não substituem suas configurações salvas.", "Enabled: add phase markers to normally completed Codex replies.": "Ativado: adiciona marcadores de fase às respostas do Codex concluídas normalmente.", "Enabled: listening on 0.0.0.0 to allow access from other devices.": "Ativado: escutando em 0.0.0.0 para permitir acesso de outros dispositivos.", "Enabled: on other devices, point the API address to {url}{panel}.": "Ativado: em outros dispositivos, aponte o endereço da API para {url}{panel}.", "Enabling this listens on all IPv4 interfaces (0.0.0.0), not just the LAN, but does not automatically expose the gateway to the internet. Actual access depends on your network and firewall settings. Changes require an app restart.": "Ao ativar, o gateway escuta em todas as interfaces IPv4 (0.0.0.0), não apenas na rede local, mas não é exposto automaticamente à internet. O acesso real depende das configurações de rede e firewall. Alterações exigem reiniciar o aplicativo.", "Endpoint": "Endpoint", "Endpoint looks like http://192.168.1.10:9000 (self-hosted usually uses http); Region is typically us-east-1.": "O Endpoint tem o formato http://192.168.1.10:9000 (auto-hospedado geralmente usa http); a Region costuma ser us-east-1.", "English": "inglês", "Enter \"IP or domain:port\". The scheme may be http:// or https:// (http is assumed if omitted). Without a port, http defaults to 3065 and https to 443. Any /m or /v1 in the address is stripped automatically.": "Informe \"IP ou domínio:porta\". O protocolo pode ser http:// ou https:// (http é assumido se omitido). Sem porta, http usa 3065 e https usa 443. Qualquer /m ou /v1 no endereço é removido automaticamente.", "Enter a client name of up to 80 characters": "Informe um nome de cliente com até 80 caracteres", "Enter a match pattern of up to 256 characters": "Informe um padrão com até 256 caracteres", "Enter a status code and press Enter": "Digite o status code e pressione Enter para adicionar", "Enter an admin account (up to 64 characters)": "Preencha a conta de administrador (até 64 caracteres)", "Enter one hostname per line, without a scheme, port or path. Match your Cloudflare configuration; the server requires an exact hostname match. The mobile app uses the connected gateway's hostname.": "Informe um hostname por linha, sem protocolo, porta ou caminho. Use os mesmos valores da Cloudflare; o servidor exige correspondência exata. O aplicativo móvel usa o hostname do gateway conectado.", "Enter sync password": "Digitar senha de sincronização", "Enter the secret key": "Digite a chave secreta", "Enter the sync password": "Digite a senha de sincronização", "Enter your current password": "Digite a senha de login atual", "Environment": "Ambiente", "Event Log Retention Days": "Dias de retenção dos logs de eventos", "Event logs": "Logs de eventos", "Every inference request on the ZCode \"Plan pool (Start Plan)\" channel must carry a freshly minted Aliyun invisible-CAPTCHA token (one-shot, expires in about 2 minutes): tokens are minted silently by the mint guard in the UI and pushed into the gateway pool, from which forwarding takes one per request. The three values here govern the restocking rhythm: ① \"Stock target\" = the guard mints more only when stock falls below it, up to it (default 3); ② \"Polling interval\" = how often the guard checks stock, default 2500 ms (only affects reaction speed — no extra minting while stock is sufficient); ③ \"Per-round mint cap\" = the most tokens minted in one round upon a shortage, default 1 (consecutive mints are fixed 500 ms apart). When requests are dense and the request log keeps showing 503 \"needs a CAPTCHA token\", raise the target and per-round cap and poll faster so the pool keeps up — the trade-off is that the upstream (Aliyun) rate-limits minting: the more and faster you mint, the likelier you trip the limit, and unused tokens expire within 2 minutes anyway, effectively burning quota — so adjust in small steps. Saving takes effect on the next restock round, no restart needed.": "Cada solicitação de inferência no canal \"Pool de planos (Start Plan)\" do ZCode deve carregar um token invisível de CAPTCHA da Aliyun recém-cunhado (de uso único, expira em cerca de 2 minutos): os tokens são cunhados silenciosamente pelo guardião de cunhagem na interface e empurrados para o pool do gateway, de onde o encaminhamento toma um por solicitação. Os três valores aqui governam o ritmo de reposição: ① \"Meta de estoque\" = o guardião só cunha mais quando o estoque cai abaixo dela, até ela (padrão 3); ② \"Intervalo de sondagem\" = com que frequência o guardião verifica o estoque, padrão 2500 ms (afeta apenas a velocidade de reação — não cunha além quando o estoque basta); ③ \"Limite de cunhagem por rodada\" = o máximo de tokens cunhados em uma rodada ao detectar falta, padrão 1 (cunhagens consecutivas são fixadas a 500 ms). Quando as solicitações forem densas e o registro mostrar 503 \"precisa de token de CAPTCHA\" em sequência, aumente a meta e o limite por rodada e acelere a sondagem para o pool acompanhar — a contrapartida é que o upstream (Aliyun) limita a frequência de cunhagem: quanto mais e mais rápido cunhar, maior a chance de esbarrar no limite, e tokens não usados expiram em 2 minutos de qualquer forma, queimando cota à toa — ajuste em passos pequenos. Salvar entra em vigor na próxima rodada de reposição, sem reinício.", "Every menu is already in this group": "Todos os menus já estão neste grupo", "Every request is routed by strategy from scratch — same behavior as \"Off\", only the session records are kept.": "Cada requisição é roteada pela estratégia do zero — mesmo comportamento de \"Desligado\", apenas os registros de sessão são mantidos.", "Every request on the ZCode plan-pool (Start Plan) channel consumes a freshly minted CAPTCHA token (one-shot, expires in 2 minutes); when stock falls below this value the UI mints more up to it. Default 3. A larger value absorbs bursts, but unused tokens expire after 2 minutes and burn the upstream risk-control quota. Allowed 1-10.": "Cada solicitação no canal do pool de planos do ZCode (Start Plan) consome um token de CAPTCHA recém-cunhado (de uso único, expira em 2 minutos); quando o estoque cair abaixo deste valor, a interface cunha mais até ele. Padrão 3. Um valor maior absorve picos, mas tokens não usados expiram em 2 minutos e queimam a cota de controle de risco do upstream. Aceita 1-10.", "Exact match": "Correspondência exata", "Exact text": "Texto exato", "Excess historical data will be deleted immediately and cannot be recovered.": "Os dados históricos excedentes serão excluídos imediatamente, sem possibilidade de recuperação.", "Executable path": "Caminho do executável", "Export Accounts": "Exportar contas", "Export canceled": "Exportação cancelada", "Export writes all accounts and custom provider definitions to a JSON file that can be copied to another machine and imported for continued use. Import merges: within the same provider, accounts are deduplicated by business identity (UID / userId / apiKey, etc.) — existing accounts only get their credentials updated and keep this machine's existing priority order; new accounts are appended to the end of the forwarding order and never displace the account currently in use; custom provider definitions are merged by id and created automatically when missing locally.": "A exportação grava todas as contas e definições de provedores personalizados em um arquivo JSON, que pode ser copiado para outra máquina e importado para continuar usando. A importação usa uma estratégia de mesclagem: dentro do mesmo provedor, as contas são deduplicadas pela identidade de negócio (UID / userId / apiKey etc.) — contas já existentes têm apenas as credenciais atualizadas e mantêm a ordem de prioridade original desta máquina; contas novas são anexadas ao final da ordem de encaminhamento e não tomam o lugar da conta em uso no momento; as definições de provedores personalizados são mescladas por id e criadas automaticamente quando ausentes nesta máquina.", "Exporting…": "Exportando…", "Exports the entire database (accounts, gateway config, event logs, request stats, debug payloads, desktop settings) into one SQL file; restoring wholesale-replaces all local data. This is a different semantic from the \"Account import / export\" above, which merges item by item: a restore swaps config, logs, and enabled states to whatever the backup machine had. The export includes logs and debug payloads by default (the file can be large); uncheck to back up business data only. Before a restore, the current data is automatically backed up to backups/ under the config directory, and you will need to log in to the panel again afterwards.": "Exporta o banco inteiro (contas, configuração do gateway, logs de eventos, estatísticas de requisições, payloads de depuração e configurações do desktop) em um arquivo SQL; a restauração substitui todos os dados locais por inteiro. É uma semântica diferente do \"Importar / exportar contas\" acima, que mescla item a item: restaurar troca configuração, logs e estados de ativação para o que a máquina do backup tinha. A exportação inclui logs e payloads de depuração por padrão (o arquivo pode ser grande); desmarque para guardar só os dados de negócio. Antes de restaurar, os dados atuais são automaticamente backupados em backups/ no diretório de configuração, e você precisará logar no painel de novo depois.", "Failed to check admin status: {message}": "Falha ao consultar o status do administrador: {message}", "Failed to clear the fallback: {message}": "Falha ao encerrar: {message}", "Failed to load client identification settings": "Falha ao carregar configurações de identificação", "Failed to load image compatibility settings": "Falha ao carregar a configuração de compatibilidade de imagens", "Failed to read cloud sync settings: {message}": "Falha ao ler as configurações de sincronização na nuvem: {message}", "Failed to read gateway info: {message}": "Falha ao ler as informações do gateway: {message}", "Failed to read remote info: {message}": "Falha ao ler as informações remotas: {message}", "Failed to read: {message}": "Falha ao ler: {message}", "Failed: {n}; {detail}": "Falhas: {n} — {detail}", "Failures matching these upstream status codes are not retried on the same account — the gateway switches to the next account and keeps trying (an account switch consumes an \"Account-Switch Retries\" slot; only when those are exhausted is the error returned to the client as-is). Type a status code from 100–599 and press Enter to add it; click × or press Backspace to delete one. Default: 402 (insufficient points). Clearing the list means any error is retried as usual.": "Falhas que correspondam a esses status codes do upstream não são reenviadas na mesma conta: o gateway passa direto para a próxima conta e continua tentando (a troca de conta consome uma das “Retries trocando de conta”; só quando elas se esgotam e a falha persiste é que o erro é retornado ao cliente como está). Digite um status code de 100–599 e pressione Enter para adicionar; clique em × ou use Backspace para remover. Padrão: 402 (pontos insuficientes). Limpar tudo significa que qualquer erro é tratado com o retry normal.", "Feature Request": "Sugestões de funcionalidades", "Feedback & Requests": "Feedback e solicitações", "Fill in model capabilities and reasoning levels the upstream never declares, using models.dev (refreshed online; the bundled snapshot always applies)": "Preenche capacidades e níveis de raciocínio que o upstream não declara, usando o models.dev (atualização online; o snapshot embutido sempre vale)", "Filter settings by provider": "Filtrar configurações por provedor", "Fingerprint masking disabled": "Mascaramento de fingerprint de saída desativado", "Fingerprint masking settings apply only to this run. Database writing failed; check the configuration directory.": "As configurações valem somente nesta execução. A gravação no banco falhou; verifique o diretório de configuração.", "Fingerprint masking settings refreshed": "Configurações de mascaramento de fingerprint atualizadas", "Fingerprint sanitizing": "Sanitização de fingerprint", "Follow Default": "Seguir padrão", "Follow model settings": "Seguir configuração do modelo", "For security, you need to register a ": "Por segurança, antes de ativar é preciso registrar uma ", "Foreground process": "Execução em primeiro plano", "Forwarding": "Encaminhamento", "Fresh data just fetched from models.dev": "Dados recém-buscados do models.dev", "From {device}, created at {time}": "De {device}, criado em {time}", "Full-database backup / restore": "Backup / restauração do banco completo", "Full-database backup is not available here (desktop only)": "Backup do banco completo não está disponível aqui (somente desktop)", "Full-database backup is not available in this environment": "O backup do banco completo não está disponível neste ambiente", "Full-database restore is not available here (desktop only)": "Restauração do banco completo não está disponível aqui (somente desktop)", "Full-database restore is not available in this environment": "A restauração do banco completo não está disponível neste ambiente", "Gateway": "Gateway", "Gateway CORS": "Acesso de outra origem ao gateway (CORS)", "Gateway CORS disabled": "CORS do gateway desativado", "Gateway CORS enabled": "CORS do gateway ativado", "Gateway CORS settings refreshed": "Configurações de CORS do gateway atualizadas", "Gateway key count": "Quantidade de chaves do gateway", "Gateway-Provided Prompt": "Interno do gateway", "General": "Geral", "Give Feedback": "Enviar feedback", "Global Configuration": "Configuração global", "Got it": "Entendi", "Group name": "Nome do grupo", "Group name, e.g. \"Favorites\"": "Nome do grupo, ex.: \"Favoritos\"", "Hidden": "Oculto", "Hide account names (show asterisks)": "Ocultar nomes das contas (mostrar asteriscos)", "Hide group {name}": "Ocultar grupo {name}", "Hide this group": "Ocultar este grupo", "Hide username": "Ocultar nome de usuário", "Hide {name}": "Ocultar {name}", "How accounts are picked when forwarding a request: ① \"Routing strategy\" sets the queueing rule — Strict order means position 1 takes every request until it can't answer (rate-limited / failing / out of quota) before the next one steps in; Load balancing rotates to the next account on every request, spreading the load across accounts. ② \"Session stickiness\" keeps the same session (same model + same opening messages) on one account wherever possible — multi-turn conversations reuse the upstream context cache, fewer account switches, less waste; Auto sticks for 5 minutes, In-session for 6 hours, Per turn and Off don't stick. The queue position (first column of the accounts table) is the foundation under every strategy; strategies are layered on top of it. Routing also has three self-healing guards: accounts that fail to forward back off for a while (starting at 15 minutes, doubling per failure, capped at 1 hour), accounts 429'd despite having quota go to the back of the queue for 30 minutes, and accounts out of quota or over their per-period token cap are held by the limiter — the first two can be toggled below as needed; the limiter is governed by each account's \"Limiter\" settings.": "Em que ordem as contas são escolhidas ao encaminhar uma requisição: ① a \"Estratégia de roteamento\" define a regra da fila — na Ordem estrita, a posição 1 atende todas as requisições até não conseguir responder (limite / falha / cota esgotada) antes de passar à próxima; no Balanceamento de carga, cada requisição vai para a próxima conta, espalhando a carga. ② A \"Aderência de sessão\" mantém a mesma sessão (mesmo modelo + mesmas mensagens iniciais) na mesma conta sempre que possível — conversas de vários turnos reutilizam o cache de contexto do upstream, menos trocas de conta e menos desperdício; Automático gruda por 5 minutos, Na sessão por 6 horas, Por turno e Desligado não grudam. A posição na fila (primeira coluna da tabela de contas) é a base de toda estratégia; as estratégias se aplicam por cima. O roteamento ainda tem três proteções de autorrecuperação: contas que falham no encaminhamento recuam um pouco (15 minutos iniciais, dobrando a cada falha, teto de 1 hora), contas 429 com cota vão para o fim da fila por 30 minutos, e contas sem cota / acima do limite de tokens do período são seguradas pelo limitador — as duas primeiras podem ser ligadas e desligadas abaixo conforme a necessidade; o limitador é governado pela configuração \"Limitador\" de cada conta.", "How it works": "Como funciona", "How many more accounts to try on failure (N = switch to at most N accounts; the account that made the first attempt does not count). Switching to another account under the same provider and switching to a different provider each count as one; once the limit is reached and the request still fails, an error is returned. Accepts 0–10; 0 means report the error immediately on failure.": "Quantas contas a mais tentar em caso de falha (preencha N = trocar por até N contas; a que fez o primeiro envio não conta). Trocar para outra conta do mesmo provedor ou para outro provedor conta igualmente como uma troca; se o limite se esgotar e a falha persistir, um erro é retornado. Valores de 0–10; 0 significa retornar o erro imediatamente após a falha.", "How many times to resend in place on the same account (not counting the first send; the whole request shares one pool, and once it is used up, any account switched to gets only one send before switching continues). Accepts 0–10; 0 means switch accounts immediately on failure.": "Quantas vezes o gateway reenvia na própria conta (sem contar o primeiro envio; a requisição inteira compartilha um único saldo e, esgotado ele, cada conta obtida na troca envia uma vez e a troca segue). Valores de 0–10; 0 significa trocar de conta imediatamente após a falha.", "How many tokens a single round may mint when a shortage is found (fixed 500 ms between back-to-back mints). Default 1: consecutive mints on one SDK instance tend to interfere with each other. A larger value restocks faster, but the more mints per round, the easier it trips the upstream risk control. 1–5 accepted.": "Quantos tokens uma mesma rodada pode cunhar ao detectar falta (intervalo fixo de 500 ms entre cunhagens seguidas). Padrão 1: cunhagens seguidas na mesma instância do SDK tendem a se interferir. Um valor maior repõe mais rápido, mas quanto mais cunhagens por rodada, mais fácil acionar o controle de risco do upstream. Aceita 1–5.", "How often the minting guard checks the stock (milliseconds). It only affects how quickly a shortage is noticed — with enough stock, the poll mints nothing. Default 2500 ms; 1000–30000 accepted.": "De quanto em quanto tempo o guarda de cunhagem olha o estoque (milissegundos). Afeta só a rapidez de perceber a falta — com estoque suficiente, o polling não cunha nada. Padrão 2500 ms; aceita 1000–30000.", "Huawei Cloud OBS": "Huawei Cloud OBS", "Human verification": "Verificação humana", "Human verification complete": "Verificação humana concluída", "Human verification failed": "Falha na verificação humana", "Human verification is still running, please wait": "A verificação humana ainda está sendo calculada, aguarde", "Identification evidence": "Evidência de identificação", "Identification evidence was not recorded": "Evidência de identificação não registrada", "Identification rule limit reached": "Limite de regras de identificação atingido", "Identify each request by its software identifiers, independently of API keys. Rule changes affect new requests only. Built-in rules update with the app; custom rules are included in backups and cloud sync.": "Identifique cada requisição pelos identificadores do software, sem depender de API Key. Alterações afetam apenas novas requisições. Regras integradas acompanham o app; regras personalizadas entram no backup e na sincronização.", "If the first choice is unavailable, the backups are tried in order.": "Se a primeira opção não estiver disponível, os alternativos são tentados em ordem.", "If you forget the password it cannot be recovered in the UI: stop the program, delete the administrator record from the database (the panelAdmin key in the kv table), then restart and register again as on first use. Commands and the database path for each deployment form are in the \"Reset administrator\" document under docs.": "Se você esquecer a senha, ela não pode ser recuperada pela interface: pare o programa, exclua o registro do administrador no banco (a chave panelAdmin na tabela kv), reinicie e registre novamente como no primeiro uso. Os comandos e o caminho do banco em cada forma de instalação estão no documento \"Redefinir administrador\" em docs.", "Image compatibility": "Compatibilidade de imagens", "Image compatibility is currently off: the two blocks below can still be edited and are kept, but nothing here applies to any request.": "A compatibilidade de imagens está desligada: os dois blocos abaixo continuam editáveis e são mantidos, mas nada disso vale para qualquer requisição.", "Image compatibility settings saved. They apply only to new requests.": "Configuração de compatibilidade de imagens salva. Ela se aplica apenas a novas solicitações.", "Image compression": "Compressão de imagens", "Image compression disabled": "Compressão de imagens desativada", "Image compression settings refreshed": "Configurações de compressão de imagens atualizadas", "Images and relevant conversation will be sent to the configured vision models, which may increase latency and cost. Confirm that these services may receive your images.": "As imagens e a conversa relevante serão enviadas aos modelos de visão configurados, o que pode aumentar a espera e o custo. Confirme que esses serviços podem receber suas imagens.", "Images are handled by the two blocks below; turning this off keeps all of the settings.": "As imagens são tratadas pelos dois blocos abaixo; desligar mantém todas as configurações.", "Images smaller than this size after decoding are kept as-is. Default 512KB, range 0-10240; 0 processes every inline image.": "Imagens menores que este tamanho após a decodificação são mantidas como estão. Padrão 512KB, faixa 0–10240; 0 processa todas as imagens embutidas.", "Images whose longest edge exceeds this value are scaled down proportionally (never enlarged). Default 2048, range 256-8192 — most vision models are fine at this size; a smaller value saves bandwidth but loses detail.": "Imagens cujo lado maior excede este valor são reduzidas proporcionalmente (nunca ampliadas). Padrão 2048, faixa 256–8192 — a maioria dos modelos de visão já fica bem nesse tamanho; um valor menor economiza tráfego, mas perde detalhes.", "Import Accounts": "Importar contas", "Import canceled": "Importação cancelada", "Import complete: {summary}": "Importação concluída: {summary}", "Import key and continue": "Importar chave e continuar", "In Effect": "Em vigor", "In the web build, interface zoom is controlled by the browser itself (Ctrl + / Ctrl -, or the zoom entry in the browser menu); this setting is not adjustable.": "No painel web, o zoom da interface é controlado pelo próprio navegador (Ctrl + / Ctrl -, ou o zoom no menu do navegador); esta opção não pode ser ajustada.", "In-container update": "Atualização no contêiner", "In-flight requests": "Requisições em andamento", "Include logs and debug payloads": "Incluir logs e payloads de depuração", "Includes: {items}": "Inclui: {items}", "Individual configuration removed for \"{label}\"": "Configuração individual de “{label}” removida", "Install as app": "Instalar como app", "Install the official identity prompt ({size})": "Instalar o system prompt de identidade oficial ({size})", "Installation cancelled": "Instalação cancelada", "Installed as an app it opens straight from the home screen icon: full screen, no address bar.": "Instalado como app, ele abre direto pelo ícone da tela inicial: em tela cheia, sem barra de endereço.", "Installer kind": "Tipo de instalador", "Installing…": "Instalando…", "Interface Language": "Idioma da interface", "Interface Zoom": "Zoom da interface", "Interface Zoom Level": "Nível de zoom da interface", "Interface language. Choices: 简体中文, 繁體中文, English, 日本語, 한국어, Português (Brasil), or System (picked automatically from the browser / system language list). Switching reloads the whole page immediately; the preference is stored only on this machine (localStorage) and does not affect accounts, keys, or forwarding.": "Idioma da interface. Opções: 简体中文, 繁體中文, English, 日本語, 한국어, Português (Brasil), ou “Sistema” (seleção automática pela lista de idiomas do navegador / sistema). Após a troca, a página inteira é atualizada na hora; essa preferência fica apenas nesta máquina (localStorage) e não afeta contas, chaves nem o encaminhamento.", "Invalid address. Enter \"IP or domain:port\", optionally with http:// or https:// — e.g. 192.168.1.23:3065": "Endereço inválido. Informe \"IP ou domínio:porta\", opcionalmente com http:// ou https:// — por exemplo 192.168.1.23:3065", "Invalid or duplicate client identifier": "Identificador de cliente inválido ou duplicado", "Invalid or duplicate identity headers: {headers}": "Cabeçalhos de identificação inválidos ou duplicados: {headers}", "JPEG quality used when re-encoding the scaled image. Default 80, range 40-95; lower means a smaller file and lower quality.": "Qualidade JPEG usada ao recodificar a imagem reduzida. Padrão 80, faixa 40–95; menor significa arquivo menor e qualidade pior.", "Japanese": "japonês", "Jianguoyun (Nutstore)": "Jianguoyun (Nutstore)", "Jianguoyun requires an app-specific password (generate it under Account info → Security), and the URL must point to a directory under /dav/.": "O Jianguoyun exige uma senha de aplicativo (gerada em Informações da conta → Segurança) e o endereço deve apontar para um diretório em /dav/.", "KB": "KB", "Keep draft and reload settings": "Manter rascunho e recarregar configurações", "Keep the images and select a vision model": "Preservar imagens e escolher um modelo de visão", "Keep the original images and conversation, and let a vision model answer this request directly.": "Preserve as imagens originais e a conversa para que um modelo de visão responda diretamente a esta solicitação.", "Kept for compatibility with older settings. Tokens are not minted automatically in batches. Each Start verification action obtains one token and stops on failure or cancellation.": "Mantido para compatibilidade com configurações antigas. Não há geração automática em lote. Cada ação Iniciar verificação obtém um token e para em caso de falha ou cancelamento.", "Key import failed: {message}": "Falha ao importar a chave: {message}", "Korean": "coreano", "LAN Access": "Acesso LAN", "Language Settings": "Configurações de idioma", "Large base64 images embedded in a conversation (screenshots, photos) both bloat the request body and raise upstream billing, which is computed from pixels. When enabled, the gateway scales images above the threshold down to the long-edge limit and re-encodes them as JPEG before forwarding — only the copy sent upstream is changed; the request log still stores the original you sent. When the same original image reappears across turns, the previous compressed result is reused instead of recomputed. Images referenced by http links, animated GIFs and SVGs are never touched; an image that would grow after re-encoding is kept as-is. Applies to chat only — image generation and editing are unaffected. On by default; turn the switch off if you do not want it.": "Imagens base64 grandes embutidas na conversa (capturas de tela, fotos) incham o corpo da requisição e elevam a cobrança do provedor, calculada por pixel. Quando ativado, o gateway reduz as imagens acima do limite até o tamanho máximo do lado maior e as recodifica em JPEG antes de encaminhar — apenas a cópia enviada ao provedor é alterada; o log de requisições continua guardando o original que você enviou. Quando a mesma imagem original reaparece ao longo dos turnos, o resultado comprimido anterior é reaproveitado em vez de recalculado. Imagens referenciadas por links http, GIFs animados e SVGs nunca são tocados; uma imagem que ficaria maior após a recodificação é mantida como está. Aplica-se apenas ao chat — geração e edição de imagens não são afetadas. Ativado por padrão; desative o interruptor se não quiser.", "Last auto sync failed": "A última sincronização automática falhou", "Last sync: {time} ({action})": "Última sincronização: {time} ({action})", "Launch at startup": "Iniciar com o sistema", "Launch it from the home screen icon: full screen, no address bar. To uninstall, long-press the icon and remove it, or clear the browser's site data.": "Abra pelo ícone na tela inicial: em tela cheia, sem barra de endereço. Para desinstalar, mantenha o ícone pressionado e remova, ou limpe os dados do site no navegador.", "Leave Endpoint empty to use the official AWS address; Region must match the bucket's region.": "Deixe o Endpoint vazio para usar o endereço oficial da AWS; a Region deve corresponder à região do bucket.", "Leave blank to use the default": "Deixe em branco para usar o padrão", "Leave blank to use the official AWS address": "Deixe em branco para usar o endereço oficial da AWS", "Leave empty = use the built-in default prompt": "Vazio = usar o system prompt padrão integrado", "Leave empty to delete matched text. Replacement text is inserted literally; $ is not a capture-group reference.": "Deixe vazio para excluir o texto correspondente. A substituição é inserida literalmente; $ não referencia grupos de captura.", "Legacy data pending migration": "Dados antigos pendentes de migração", "Let Codex collapse intermediate work after the final answer. Phase markers are added only to strictly identified Codex Responses requests, independently of report categories and client declarations. Only non-empty, normally completed replies without tool calls receive final_answer; text before tool calls receives commentary. Errors, truncation, missing completion signals and unknown finish reasons never receive a final-answer marker. Off by default; answer text, model reasoning and usage are unchanged.": "Permite que o Codex recolha o trabalho intermediário após a resposta final. Os marcadores de fase são adicionados somente a requisições Responses identificadas estritamente como Codex, independentemente das categorias dos relatórios ou das declarações do cliente. Apenas respostas não vazias, concluídas normalmente e sem chamadas de ferramentas recebem final_answer; explicações antes das chamadas recebem commentary. Erros, truncamento, ausência de sinal de conclusão e motivos de término desconhecidos não recebem marcador de resposta final. Desativado por padrão; não altera o texto, o raciocínio do modelo nem o consumo.", "License texts are bundled with the app and available offline. Opening project source links requires an internet connection.": "Os textos das licenças estão incluídos no aplicativo e podem ser consultados offline. Abrir os links de origem dos projetos requer conexão com a internet.", "Lightweight mode": "Modo leve", "Lightweight mode (releases UI memory when the window is closed)": "Modo leve (liberar a memória da interface ao fechar a janela)", "Lightweight mode is on: closing the window destroys the UI process (freeing about 200 MB of memory) while the gateway continues in the background; while the UI is destroyed, the ZCode plan-pool (Start Plan) channel is unavailable and affected requests will note the reason in the request log": "O modo leve está ativado: fechar a janela destrói o processo da interface (liberando cerca de 200 MB de memória) enquanto o gateway continua em segundo plano; com a interface destruída, o canal do pool de planos do ZCode (Start Plan) fica indisponível e as solicitações afetadas registrarão o motivo no log de solicitações", "Lightweight mode off: closing the window only hides it, the UI process stays in memory, and it opens instantly": "Modo leve desativado: fechar a janela apenas a oculta, o processo da interface permanece na memória e reabrir é instantâneo", "Lightweight mode on: closing the window destroys the UI process (freeing about 200MB of memory) while the gateway keeps running in the background; while the UI is destroyed, the ZCode activity-plan channel is unavailable, and affected requests are noted in the request logs with the reason": "Modo leve ativado: fechar a janela destrói o processo da interface (libera cerca de 200MB de memória) e o gateway continua em segundo plano; enquanto a interface está destruída, o canal do Plano de evento da ZCode fica indisponível e as requisições relacionadas registram o motivo nos logs de requisições", "Linux package (deb)": "Pacote Linux (deb)", "Listen address": "Endereço de escuta", "Load balancing": "Balanceamento de carga", "Loading provider settings…": "Carregando configurações de provedores…", "Local APK version": "Versão do APK neste aparelho", "Local UI version": "Versão da interface neste aparelho", "Local app version": "Versão do app neste aparelho", "Location": "Local", "Location and ports": "Local e portas", "Log file": "Arquivo de log", "Log record limit": "Limite de registros de log", "Login CAPTCHA": "CAPTCHA de login", "Logs and request logs are limited by both retention days and record count. Logs default to 30 days and 10,000 records, with capacity allocated proportionally by level; debug details are kept for at most 3 days. Request logs default to 99999 days and 1,000,000 records; excess records are removed oldest first together with their raw bodies. Daily aggregates default to 99999 days and are limited only by days; request log count cleanup does not affect them. Days accept 1–99999 and counts accept 1–100000000. Lowering any setting and confirming immediately removes excess data, which cannot be recovered.": "Logs e logs de requisições são limitados tanto pelos dias de retenção quanto pela quantidade de registros. Os logs têm padrão de 30 dias e 10.000 registros, com capacidade distribuída proporcionalmente por nível; detalhes de depuração são mantidos por no máximo 3 dias. Os logs de requisições têm padrão de 99999 dias e 1.000.000 de registros; o excedente é removido dos mais antigos para os mais novos junto com seus corpos originais. Os agregados diários têm padrão de 99999 dias e são limitados apenas pelos dias; a limpeza por quantidade dos logs de requisições não os afeta. Os dias aceitam 1–99999 e a quantidade aceita 1–100000000. Reduzir qualquer configuração e confirmar remove o excedente imediatamente, sem possibilidade de recuperação.", "Longest wait for compatibility processing": "Espera máxima do processamento de compatibilidade", "Main process bridge unavailable": "Ponte com o processo principal indisponível", "Make a Suggestion": "Enviar sugestão", "Manage plugins": "Gerenciar plugins", "Manage provider-specific options. Changes apply to all accounts for that provider on the current gateway.": "Gerencie opções específicas por provedor. As alterações se aplicam a todas as contas desse provedor no gateway atual.", "Managed": "Assumido pelo gateway", "Masking rules": "Regras de mascaramento", "Match pattern": "Padrão de correspondência", "Match type": "Tipo de correspondência", "Matched evidence: {header} · {pattern}": "Evidência correspondente: {header} · {pattern}", "Matches the exact text, case-sensitively. Leading and trailing whitespace is preserved.": "Corresponde ao texto exato, diferenciando maiúsculas e minúsculas. Os espaços iniciais e finais são preservados.", "Max long-edge pixels": "Limite do lado maior (px)", "Maximum idle time allowed between adjacent chunks of a streaming response (seconds); the timer restarts on each new chunk. Default 300 seconds, range 1–3600.": "Tempo máximo de inatividade permitido entre dados adjacentes de uma resposta em streaming (segundos), com a contagem reiniciada a cada novo dado recebido; padrão 300 segundos, faixa 1~3600.", "Maximum image adaptation wait (seconds)": "Espera máxima para adaptação (segundos)", "Maximum time allowed to read a complete non-streaming response body (seconds). Default 300 seconds, range 1–3600.": "Tempo máximo permitido para ler o corpo completo de uma resposta não streaming (segundos), padrão 300 segundos, faixa 1~3600.", "Maximum time to establish the upstream TCP/TLS connection or proxy tunnel (seconds). Default 30 seconds, range 1–3600.": "Tempo máximo de espera para estabelecer a conexão TCP/TLS ou o túnel de proxy com o upstream (segundos), padrão 30 segundos, faixa 1~3600.", "Maximum time to wait for the upstream's response headers after the request is sent (seconds). Default 300 seconds, range 1–3600.": "Tempo máximo de espera pelos cabeçalhos de resposta do upstream após o envio da requisição (segundos), padrão 300 segundos, faixa 1~3600.", "Message roles": "Papéis das mensagens", "Minimize to tray when the window is closed": "Minimizar para a bandeja ao fechar a janela", "Minimum automatic upload interval": "Intervalo mínimo de upload automático", "Mismatch": "Divergente", "Mode": "Modo", "Mode changed to \"{mode}\"": "Modo alterado para “{mode}”", "Model that takes over the answer": "Modelo que assume a resposta", "Models for {way}": "Modelos para {way}", "Move a menu into \"{name}\"": "Mover um menu para \"{name}\"", "Move a menu into {name}": "Mover um menu para {name}", "Move down": "Mover para baixo", "Move into \"{name}\"": "Mover para \"{name}\"", "Move rule down": "Mover regra para baixo", "Move rule up": "Mover regra para cima", "Move up": "Mover para cima", "Multi-select across providers; only images these models cannot read are handled.": "Seleção múltipla entre provedores; só são tratadas as imagens que esses modelos não conseguem ler.", "Multi-select across providers; requests from these models are handed over to the vision model as a whole.": "Seleção múltipla entre provedores; as requisições desses modelos são entregues inteiras ao modelo de visão.", "Network access": "Acesso pela rede", "Network access settings are not supported in this environment": "As configurações de acesso pela rede não estão disponíveis neste ambiente", "New client category": "Nova categoria de cliente", "New group": "Novo grupo", "New group name": "Nome do novo grupo", "New password": "Nova senha", "New password must differ from the current one": "A nova senha deve ser diferente da atual", "New requests save upstream debug payloads and downstream bodies after this is enabled; past requests cannot be backfilled. Only the most recent 500 upstream debug payloads are kept. Counts for both sides are shown under Data → Data storage. Turning this off does not delete saved payloads; choose Clear raw payloads only in request logs to clear both sides together.": "Após ativar, novas requisições salvam os payloads de depuração do upstream e os corpos do downstream; requisições anteriores não podem ser recuperadas. Apenas os 500 payloads mais recentes do upstream são mantidos. As contagens dos dois lados aparecem em Dados → Armazenamento de dados. Desativar não exclui os payloads salvos; selecione Limpar apenas os payloads nos logs de requisições para limpar os dois lados juntos.", "New requests will no longer use this rule. Historical records stay unchanged.": "Novas requisições deixarão de usar esta regra. Os registros históricos permanecem inalterados.", "Next automatic retry: {time}": "Próxima tentativa automática: {time}", "Nextcloud": "Nextcloud", "No accounts to export": "Não há contas para exportar", "No administrator is registered yet. Enabling Gateway → Network access → Allow other devices to access the gateway guides you through registration. You can also register from the sign-in page.": "Nenhum administrador foi registrado. Ativar Gateway → Acesso pela rede → Permitir que outros dispositivos acessem o gateway inicia o registro. Você também pode se registrar pela página de login.", "No administrator registered: the management API does not require sign-in. Enabling \"Allow LAN access\" walks you through registration; you can also register from the login page.": "Nenhum administrador registrado: a API de gerenciamento não exige login. Ativar \"Permitir acesso pela LAN\" conduz ao registro; você também pode registrar pela página de login.", "No custom rules; built-in identification is active. You can also add a rule from request details.": "Sem regras personalizadas; a identificação integrada está ativa. Você também pode adicionar regras nos detalhes da requisição.", "No data loaded yet.": "Nenhum dado carregado ainda.", "No editable provider settings": "Nenhuma configuração de provedor editável", "No known client matched": "Nenhum cliente conhecido identificado", "No menus are shown in the sidebar. Turn on the ones you need under Settings → Display → Sidebar menus.": "Nenhum menu aparece na barra lateral. Ative os que precisar em Configurações → Exibição → Menus da barra lateral.", "No model is confirmed to support images. Confirm its capability in Model Management first.": "Nenhum modelo tem suporte a imagens confirmado. Confirme a capacidade em Gerenciamento de Modelos primeiro.", "No models selected yet, so this block does nothing for now.": "Nenhum modelo selecionado, então este bloco ainda não faz nada.", "No recent samples matched; future requests may still match.": "Nenhuma amostra recente correspondeu; requisições futuras ainda podem corresponder.", "No refresh needed this time": "Nenhuma atualização necessária desta vez", "No servers yet. Tap \"Add\" at the top right and enter the IP or domain and port of the machine running the gateway.": "Nenhum servidor ainda. Toque em \"Adicionar\" no canto superior direito e informe o IP ou domínio e a porta da máquina que roda o gateway.", "No session detection: every request is routed by strategy from scratch.": "Sem detecção de sessão: cada requisição é roteada pela estratégia do zero.", "No snapshot exists at that remote path yet; this is the first upload.": "Ainda não há snapshot nesse caminho remoto; este é o primeiro envio.", "No sync data available to download on the remote": "Não há dados de sincronização para baixar no remoto", "No vision analysis model is configured": "Nenhum modelo de análise visual configurado", "No vision model is available yet.": "Ainda não há modelo de visão disponível.", "Non-Streaming Timeout": "Timeout de resposta não streaming", "Normalizing roles: developer-role messages are rewritten to system before forwarding.": "Normalizando papéis: mensagens com papel developer são reescritas para system antes do encaminhamento.", "Not configured": "Não configurado", "Not configured individually: mode, prompt file, and text all follow the global configuration above (currently \"{mode}\").": "Sem configuração individual: modo, arquivo de prompt e texto seguem a configuração global acima (no momento, “{mode}”).", "Not registered": "Não registrado", "Not synced yet.": "Ainda não sincronizado.", "Note: this provider's \"Gateway-Provided Prompt\" switch is currently off; edited text takes effect only after the switch is turned on.": "Atenção: o switch “Interno do gateway” deste provedor está desativado; o texto alterado só passa a valer quando o switch for ativado.", "Number notation": "Notação numérica", "Of the latest {window} requests, {scanned} have evidence, {matched} match, and {applied} would use this rule.": "Das últimas {window} requisições, {scanned} têm evidências, {matched} correspondem e {applied} usariam esta regra.", "Off by default for new installations and upgrades. Configure before enabling; disabling keeps your settings.": "Desativado por padrão em novas instalações e atualizações. Configure antes de ativar; desativar mantém a configuração.", "Off by default. Changes take effect immediately, no restart needed; while off, cross-origin requests are stopped by the preflight.": "Desativado por padrão. As mudanças valem na hora, sem reiniciar; enquanto estiver desativado, as requisições de outra origem são barradas no preflight.", "Off by default. Enabling takes effect on the next Codex request without a restart; phase markers are only added to Codex-origin /v1/responses requests, other clients and /v1/chat/completions are unaffected.": "Desativado por padrão. Ao ativar, vale já na próxima requisição do Codex, sem reiniciar; os marcadores de fase são adicionados apenas a requisições /v1/responses com origem Codex, e outros clientes e /v1/chat/completions não são afetados.", "Off: browsers cannot reach the gateway cross-origin.": "Desativado: o navegador não consegue se conectar diretamente ao gateway de outra origem.", "Off: client system templates go upstream as-is and may be falsely blocked by content review (400).": "Desativado: os templates do system do cliente vão ao upstream como estão e podem ser bloqueados por engano na revisão de conteúdo (400).", "Off: developer-role messages are sent upstream as-is; upstreams that do not know the role return an error (400).": "Desativado: mensagens com papel developer vão para o upstream como estão; upstreams que não conhecem o papel retornam erro (400).", "Off: no raw payloads are saved while forwarding.": "Desativado: nenhum payload bruto é salvo durante o encaminhamento.", "Off: the gateway listens only on 127.0.0.1 and is reachable only from this machine.": "Desativado: o gateway escuta apenas 127.0.0.1 e somente esta máquina pode acessá-lo.", "Offline cache is off": "O cache offline está desativado", "On (up to {n} rounds)": "Ligado (até {n} rodadas)", "On Synology, enable the service under Control Panel → Application Portal → WebDAV; the default ports are 5005 (HTTP) / 5006 (HTTPS).": "No Synology, ative o serviço em Painel de Controle → Portal de Aplicativos → WebDAV; as portas padrão são 5005 (HTTP) / 5006 (HTTPS).", "On by default. Hits are recorded in the request log's \"sensitive\" tag (hover to see which rules matched). This only changes the copy sent upstream; the response content the client sees is unchanged.": "Ativado por padrão. Os detalhes das ocorrências são registrados na tag “PS” dos logs de requisições (passe o mouse para ver quais regras foram acionadas). Esta opção altera apenas a cópia enviada ao upstream; o conteúdo da resposta que o cliente vê não muda.", "On by default. Only the copy sent upstream is changed; the response and the original image seen by the client stay the same, and the request log stores the original image from the client rather than the compressed version. Applies to the chat path only — image generation and editing do not go through it. Changes take effect on the next request, no restart needed.": "Ativado por padrão. Apenas a cópia enviada ao provedor é alterada; a resposta e a imagem original vista pelo cliente permanecem iguais, e o log de requisições guarda a imagem original do cliente, não a versão comprimida. Aplica-se somente ao caminho de chat — geração e edição de imagens não passam por aqui. As alterações valem a partir da próxima requisição, sem reiniciar.", "Once LAN access is on, the admin API requires signing in. Set an admin account and password; registration finishes and the enablement flow continues automatically.": "Com o acesso LAN ativado, a interface de administração exige login. Defina a conta de administrador e a senha; concluído o registro, o fluxo de ativação continua automaticamente.", "Once disabled, the admin UI is no longer exposed over the LAN — only the desktop app on this machine can manage it; API forwarding that is already enabled is unaffected.": "Após desativar, a interface de administração deixa de ser servida na LAN e só o programa desktop local pode gerenciá-la; o encaminhamento de API já ativado não é afetado.", "Once disabled, the gateway goes back to listening only on 127.0.0.1 and devices on the LAN can no longer reach it; configured gateway keys and accounts are unaffected.": "Após desativar, o gateway volta a escutar apenas 127.0.0.1 e os dispositivos da LAN deixam de conseguir acessá-lo; as chaves do gateway e as contas já configuradas não são afetadas.", "Once enabled, closing the window does not merely hide it — the UI window is destroyed entirely: WebView2's six resident processes (about 200MB of memory) exit with it, while gateway forwarding, scheduled check-ins, and balance queries keep running in the background process, unaffected; to get the UI back, click the tray icon (a cold WebView start takes about 1 second). Note: while the UI is destroyed, the verification-code tokens for the \"ZCode activity plan\" channel are minted by the UI and cannot be replenished — requests going through that channel land in the request logs as 503 (with the reason stated), and reopening the UI restores them automatically. This switch only matters when \"Minimize to tray when the window is closed\" is on; minimizing the window is unaffected.": "Com isto ativado, fechar a janela não é apenas ocultá-la: a janela da interface é destruída por completo — os seis processos residentes do WebView2 por baixo dela (cerca de 200MB de memória) são encerrados junto, enquanto o encaminhamento do gateway, o check-in agendado e a consulta de saldo continuam nos processos em segundo plano, sem serem afetados; quando precisar da interface, clique no ícone da bandeja para reabri-la (a inicialização a frio do WebView leva cerca de 1 segundo). Atenção: enquanto a interface está destruída, os tokens de captcha do canal do Plano de evento da ZCode são forjados pela interface e não podem ser repostos — requisições por esse canal caem nos logs de requisições com status 503 (com o motivo registrado) e se recuperam automaticamente ao reabrir a interface. Este switch só faz sentido quando “Minimizar para a bandeja ao fechar a janela” está ativado; minimizar a janela não é afetado.", "Once enabled, other devices on the LAN can open this machine's IP in a browser to reach the admin panel (signing in with an admin account is required).": "Após abrir, o navegador de outros dispositivos na LAN pode acessar o painel de administração abrindo o IP desta máquina (é preciso entrar com a conta de administrador).", "Once enabled, the gateway listens on all network interfaces, and devices on the same LAN can point the API address at this machine's IP to share it; the admin API then requires an admin session or a gateway key, and the forwarding API refuses service when no key is enabled (a key named \"Default\" is created automatically at that point).": "Após ativar, o gateway passa a escutar todas as interfaces de rede e dispositivos na mesma LAN podem usar a API apontando o endereço para o IP desta máquina; a interface de administração passa a exigir sessão de administrador ou chave do gateway, e a interface de encaminhamento também recusa atendimento enquanto não houver nenhuma chave ativa (nesse caso, uma chave chamada “Padrão” é criada automaticamente).", "Once enabled, the gateway saves every forward's **request to the upstream** (request headers + request body) and **the upstream's response** (status code + response headers + response body) in full locally, for viewing under \"Details\" on the request logs page; the \"Conversation preview\" in request details also depends on this switch — it saves the client's request body and the gateway's response body (each truncated to 128 KiB), and with the switch off there is no data to preview. Credential fields in request headers such as Authorization, Cookie, and API Key are always replaced with [redacted] and never written to disk in plain text; request and response bodies are saved as-is (they may contain your conversation content). Only the most recent 500 upstream payloads are kept; older ones are discarded. This is a temporary switch for troubleshooting — turn it off when you no longer need it.": "Com isto ativado, o gateway salva localmente, na íntegra, **as requisições enviadas ao upstream** (cabeçalhos + corpo) e **as respostas retornadas pelo upstream** (status code + cabeçalhos + corpo) de cada encaminhamento, para consulta em “Detalhes” na página de logs de requisições; a “Prévia da conversa” nos detalhes da requisição também depende deste switch — ela salva o corpo da requisição do cliente e o corpo da resposta do gateway (cada um truncado em 128 KiB), e com o switch desativado não há dados para pré-visualizar. Campos de credenciais nos cabeçalhos, como Authorization, Cookie e API Key, são sempre substituídos por [redacted] e nunca gravados em texto puro; corpos de requisição e de resposta são salvos como estão (podem conter o conteúdo das suas conversas). Só os 500 payloads de upstream mais recentes são mantidos; os mais antigos são descartados quando o limite é excedido. É um switch temporário para diagnóstico; recomenda-se desativá-lo quando não for necessário.", "Once enabled, the sign-in page completes verification in the browser in the background (imperceptible to a real person), while every scripted attempt must first solve a challenge — brute-forcing and mass registration become significantly more expensive. This only affects panel sign-in / registration, not the API keys used by API clients.": "Com isto ativado, a página de login conclui a verificação automaticamente em segundo plano no navegador (imperceptível para pessoas reais), enquanto cada tentativa de script precisa resolver um desafio — o custo de força bruta e de registro em massa sobe bastante. Afeta apenas o login / registro do painel, nada a ver com a API Key dos clientes de API.", "One .a2ab file restores data on another machine without separately copying keys for accounts, gateway keys, GitHub tokens, or cloud sync credentials. Plugin programs and files outside the database are not included.": "Um único arquivo .a2ab restaura os dados em outra máquina, sem copiar separadamente as chaves de contas, keys do gateway, tokens do GitHub ou credenciais de sincronização. Programas de plugins e arquivos fora do banco não estão incluídos.", "Online refresh for models.dev turned off": "Atualização online do models.dev desativada", "Only PNG, JPG and WebP images are supported for logos": "O logo aceita apenas imagens PNG, JPG e WebP", "Only affects how deeply the image-reading step thinks; both blocks share this choice.": "Afeta apenas a profundidade de raciocínio na etapa de leitura da imagem; os dois blocos compartilham esta escolha.", "Only affects panel sign-in and registration, not API key requests. Changes take effect after saving and do not sign out existing sessions.": "Afeta apenas o login e o cadastro no painel, não chamadas com chaves de API. Entra em vigor ao salvar e mantém as sessões existentes.", "Only clears the key stored in this browser; the gateway is untouched": "Remove apenas a chave salva neste navegador; o gateway não é afetado", "Only providers configured individually are listed; the rest use the global configuration above": "Só lista os provedores com configuração individual; os demais seguem a configuração global acima", "Only providers with an installed, enabled plugin that declares settings appear here. Check installation and activation on the Plugins page.": "Aparecem aqui apenas provedores com um plugin instalado e ativado que declare opções de configuração. Confira a instalação e a ativação na página Plugins.", "Only requests that happen after turning this on are recorded (past ones can't be backfilled). Payloads live in the local database and only the most recent 500 are kept (the oldest are dropped beyond that); the count shows under \"Data → Data storage\" on the left as \"Debug payloads\".": "Só requisições que acontecerem depois de ligar são registradas (as passadas não podem ser recuperadas). Os payloads ficam no banco de dados local e só os 500 mais recentes são mantidos (os mais antigos são descartados); a contagem aparece em \"Dados → Armazenamento de dados\", à esquerda, como \"Payloads de depuração\".", "Only requests that occur after this is enabled are recorded (past requests cannot be recovered), and the \"Conversation preview\" in request logs also starts saving raw bodies. Upstream payloads are stored in the local database, keeping only the most recent 500 (the oldest are discarded when the limit is exceeded); the count is shown under \"Data → Data Storage\" → \"Debug Payloads\".": "Com isto ativado, apenas requisições novas são registradas (as requisições passadas não podem ser recuperadas), e a “Prévia da conversa” nos logs de requisições também passa a salvar os corpos originais. Os payloads de upstream ficam no banco de dados local, mantendo somente os 500 mais recentes (os mais antigos são descartados quando o limite é excedido); a contagem aparece em “Payloads de debug”, na seção “Dados → Armazenamento de dados”, à esquerda.", "Only saved provider settings are listed here. Unconfigured providers follow the global settings and can be added manually from the dropdown. Saved modes, files and prompt text override the global settings; Follow Default removes only that provider's mode, file and text overrides. For ZCode's Start Plan, the plugin assembles three blocks by default and merges the client's system text into the third, without creating a replacement rule. Manually edited gateway prompt blocks and a disabled assembly switch still take precedence; acceptance depends on the upstream rules.": "Somente as configurações de provedores já salvas aparecem aqui. Provedores não configurados seguem as configurações globais e podem ser adicionados manualmente na lista. Modos, arquivos e textos salvos têm prioridade sobre os globais; Seguir padrão remove apenas essas substituições do provedor. Para o Start Plan da ZCode, o plugin monta três blocos por padrão e incorpora o system do cliente ao terceiro, sem criar uma regra de substituição automaticamente. Blocos do prompt do gateway editados manualmente e a opção de desativar a montagem continuam tendo prioridade; a aceitação depende das regras do upstream.", "Only sum accounts visible under the current filter": "Somar apenas as contas visíveis no filtro atual", "Only the model and reasoning level are reused, not the vision service's internal Key. The current request's permissions still apply.": "Apenas o modelo e o nível de raciocínio são reutilizados, não a Key interna do serviço de visão. As permissões da solicitação atual continuam valendo.", "Only this forwarded copy is changed. The client's selection and all current and historical images are preserved.": "Apenas a cópia encaminhada é alterada. A seleção do cliente e todas as imagens atuais e anteriores são preservadas.", "Open-source license": "Licença de código aberto", "Operating system": "Sistema operacional", "Optional. Some services (such as CSTCloud Data Capsule) validate the credential's bound client type via the User-Agent; if so, enter a string containing that type name (for example rclone/v1.67.0). Leave blank to keep the default.": "Opcional. Alguns serviços (como o CSTCloud Data Capsule) validam pelo User-Agent o tipo de cliente vinculado à credencial; nesse caso, informe uma string que contenha o nome do tipo (por exemplo, rclone/v1.67.0). Deixe em branco para manter o padrão.", "Options and defaults come from plugins. Plugin updates do not overwrite your saved changes. Switching providers keeps unsaved edits.": "As opções e os valores padrão vêm dos plugins. Atualizações de plugins não sobrescrevem suas alterações salvas. Trocar de provedor mantém as edições não salvas.", "Origin declarations are disabled and were ignored.": "As declarações de origem estão desativadas e foram ignoradas.", "Origin declarations for this category will no longer be accepted. Historical records retain their original names and usage.": "Declarações desta categoria não serão mais aceitas. Os registros históricos mantêm os nomes e o uso originais.", "Original license text": "Texto original da licença", "Overridden by higher priority": "Substituída por prioridade superior", "Overridden by {source}; the manual setting is not currently active": "Substituído por {source}; a configuração manual não está ativa no momento", "Override only the selected model from the selected provider; all others follow the global settings.": "Substitui apenas a configuração do modelo e provedor selecionados; os demais seguem a configuração global.", "Oversized, malformed or undownloadable images are not treated as unsupported by the model.": "Imagem grande demais, formato inválido ou falha no download não contam como modelo sem suporte a imagens.", "Overview": "Visão geral", "Panel login": "Login do painel", "Panel port": "Porta do painel", "Passthrough": "Passthrough", "Passthrough client system": "Passthrough do system do cliente", "Passthrough client system (default)": "Passthrough do system do cliente (padrão)", "Password encrypted · Recovery keys included": "Criptografado com senha · Chaves incluídas", "Password must be at least 8 characters": "A senha deve ter pelo menos 8 caracteres", "Password, file, or key validation failures leave the main database unchanged. If replacement fails, restoration is attempted automatically; the error above reports the actual outcome.": "Falhas na validação da senha, do arquivo ou das chaves não alteram o banco principal. Se a substituição falhar, a restauração será tentada automaticamente; o erro acima informa o resultado real.", "Path to a UTF-8 text file. Leave empty to use the built-in default prompt (a general coding-assistant prompt with no template sentences the upstream would block). Only applies in Replace / Append mode; passthrough mode does not read it.": "Caminho de um arquivo de texto UTF-8; deixe vazio para usar o system prompt padrão integrado (um system prompt genérico de assistente de código, sem nenhuma frase de template que o upstream bloqueie). Só tem efeito nos modos “Substituir / Anexar”; o modo Passthrough não o lê.", "Per-Provider Configuration": "Por provedor", "Per-model overrides": "Configuração por modelo", "Per-provider rotation": "Rodízio por provedor", "Per-request records on the \"Request Logs\" page. Defaults to 99999 days (about 274 years — kept in full for practical purposes); range 1–99999 days.": "Registros de cada requisição na página “Logs de requisições”. Padrão de 99999 dias (retenção praticamente total); aceita de 1 a 99999 dias.", "Per-request records on the Request Logs page. Defaults to 99999 days; accepts 1–99999 days. The record limit also applies.": "Registros por requisição na página de logs de requisições. Padrão de 99999 dias; aceita 1–99999 dias. O limite de registros também se aplica.", "Per-round mint cap": "Limite de cunhagem por rodada", "Percentage readings (such as OpenCode Go or Antigravity) cannot be summed; the band shows the group's lowest remaining percentage.": "Leituras percentuais (como OpenCode Go ou Antigravity) não podem ser somadas; a faixa mostra a menor porcentagem restante do grupo.", "Pinned": "Fixo", "Pinned egress": "Saída fixada", "Please enter a group name": "Informe um nome de grupo", "Please enter your current password": "Digite a senha atual", "Poll interval": "Intervalo de polling", "Prefer vision models in the current route": "Priorizar modelos de visão da rota atual", "Prefix": "Prefixo", "Preserve text, code, numbers, layout and state in the images. Stop if reading fails; never remove images and continue answering.": "Preserve texto, código, números, disposição e estado nas imagens. Pare se a leitura falhar; nunca remova imagens para continuar respondendo.", "Preset": "Predefinição", "Preview does not call a model or modify historical records.": "A prévia não chama modelos nem modifica registros históricos.", "Preview matches": "Pré-visualizar correspondências", "Previewing…": "Gerando prévia…", "Priority: valid origin declaration, custom rules in order, then built-in rules. If a relay removes the original identifier, the original software cannot be inferred automatically.": "Prioridade: declaração válida, regras personalizadas em ordem e regras integradas. Se um intermediário remover o identificador original, não será possível inferir automaticamente o software de origem.", "Process PID": "PID do processo", "Processing mode": "Modo de processamento", "Product name": "Nome do produto", "Product names cannot include slashes or versions. Use prefix matching.": "Nomes de produto não podem incluir barras ou versões. Use correspondência por prefixo.", "Profile": "Perfil", "Project source": "Origem do projeto", "Prompt File": "Arquivo de prompt", "Prompt Text": "Texto do prompt", "Prompt configured individually for \"{label}\"": "Prompt configurado individualmente para “{label}”", "Prompt file updated": "Arquivo de prompt atualizado", "Prompt text updated": "Texto do prompt atualizado", "Provider": "Provedor", "Provider / Model Support Request": "Solicitar suporte a provedor / modelo", "Provider and model": "Provedor e modelo", "Provider settings saved": "Configurações do provedor salvas", "Provider-specific settings": "Configurações específicas do provedor", "Providers still follow priority; only accounts within the same provider take turns. For preferring a few providers without pinning any single account.": "Os provedores seguem a prioridade; só as contas dentro do mesmo provedor se alternam. Para preferir alguns provedores sem prender nenhuma conta específica.", "QQ groups · Telegram": "Grupos do QQ · Telegram", "Queue Wait Count": "Tentativas de espera na fila", "Queue Wait Seconds": "Segundos de espera na fila", "Queueing": "Espera na fila", "Queueing settings refreshed": "Configurações de espera na fila atualizadas", "Range 5–120 seconds, also bounded by the original request timeout.": "Faixa de 5 a 120 segundos, também limitada pelo tempo da requisição original.", "Rate-limited accounts": "Contas limitadas", "Re-encode quality": "Qualidade de recodificação", "Re-encrypted {n} credentials with local keys. Existing keys were not overwritten.": "{n} credenciais recriptografadas com as chaves locais. As chaves existentes não foram sobrescritas.", "Re-enter the new password": "Digite a nova senha novamente", "Reading remote…": "Lendo o remoto…", "Reasoning level of the vision model": "Nível de raciocínio do modelo de visão", "Reasoning level, unknown image capability, wait limit": "Nível de raciocínio, capacidade de imagem desconhecida, limite de espera", "Record count": "Quantidade de registros", "Reference stock target: 3 by default, from 1 to 10. It only affects the stock display; falling below it never generates tokens or opens verification automatically.": "Meta de referência do estoque: padrão 3, entre 1 e 10. Afeta apenas a exibição; ficar abaixo da meta nunca gera tokens nem abre a verificação automaticamente.", "Refresh": "Atualizar", "Refresh failed: {message}": "Falha na atualização: {message}", "Region": "Região (Region)", "Register & Enable": "Registrar e ativar", "Register Admin Account": "Registrar conta de administrador", "Registering…": "Registrando…", "Regular expression": "Expressão regular", "Reload settings": "Recarregar configuração", "Reloading replaces the current unsaved draft.": "Recarregar substitui o rascunho atual não salvo.", "Remote data is incompatible with this version": "Os dados remotos são incompatíveis com esta versão", "Remote path: {path}": "Caminho remoto: {path}", "Remote root directory": "Diretório raiz remoto", "Removed the API key stored in this browser": "A API key salva neste navegador foi removida", "Rename": "Renomear", "Rename client category": "Renomear categoria de cliente", "Renaming changes only the category label, without splitting past usage or reclassifying historical requests.": "Renomear altera apenas o nome exibido, sem dividir o uso anterior ou reclassificar requisições históricas.", "Repeat cleanup": "Repetir limpeza", "Repeat until unchanged (regular-expression deletion only)": "Repetir até não haver mudanças (somente exclusão por expressão regular)", "Replace": "Substituir", "Replace = delete all client system / developer messages and substitute the gateway's prompt; Append = keep the client's content and just insert one extra prompt after the leading system blocks. Both only change the copy sent upstream; the response the client sees is unchanged.": "Substituir = todas as mensagens system / developer do cliente são apagadas e trocadas pelo prompt do gateway; Anexar = o conteúdo do cliente é mantido e apenas um item a mais é inserido depois dos blocos system do início. Os dois alteram somente a cópia enviada ao upstream; a resposta que o cliente vê não muda.", "Replace and restore": "Substituir e restaurar", "Replace with gateway prompt": "Substituir pelo prompt do gateway", "Replace your-server and USERNAME in the URL with your own; the directory is created automatically if missing.": "Substitua your-server e USERNAME na URL pelos seus dados; o diretório é criado automaticamente se não existir.", "Replacement text": "Texto de substituição", "Replacement text must not exceed {max} characters": "O texto de substituição deve ter no máximo {max} caracteres", "Report Days": "Dias do relatório", "Request Records": "Registros de requisições", "Request Retries": "Retry de requisições", "Request Timeouts": "Timeout de requisição", "Request log record limit": "Limite de registros de requisições", "Request log retention (days)": "Retenção dos logs de requisições (dias)", "Requests from these models are answered by an available vision model in the current route instead of the original model.": "As requisições desses modelos são respondidas por um modelo de visão disponível na rota atual, no lugar do modelo original.", "Require ALTCHA human verification (proof of work) for sign-in / registration": "Login / registro exigem a verificação humana ALTCHA (proof of work)", "Required for encrypted backups; leave blank for legacy SQL": "Obrigatória para backup criptografado; opcional para SQL antigo", "Reset administrator": "Redefinir administrador", "Reset clears the administrator account and password, returning the panel to the \"not registered\" state.": "A redefinição apaga a conta e a senha do administrador e devolve o painel ao estado \"não registrado\".", "Response Headers Timeout": "Timeout de espera de resposta", "Restore Defaults": "Restaurar padrões", "Restore Official Text": "Restaurar o texto oficial", "Restore canceled": "Restauração cancelada", "Restore database": "Restaurar o banco", "Restore default brand": "Restaurar marca padrão", "Restore default logo": "Restaurar logo padrão", "Restore default rules": "Restaurar regras padrão", "Restore default sidebar": "Restaurar barra lateral padrão", "Restore failed: {message}": "Falha na restauração: {message}", "Restore from cloud": "Restaurar da nuvem", "Restore full backup": "Restaurar backup completo", "Restore plugin default": "Restaurar padrão do plugin", "Restored the default groups: Overview / Forwarding / Diagnostics / System": "Grupos padrão restaurados: Visão geral / Encaminhamento / Diagnóstico / Sistema", "Restoring…": "Restaurando…", "Result of the last successful refresh (stored in the local database)": "Resultado da última atualização bem-sucedida (guardado no banco local)", "Results are reused only within the same conversation, question and permission scope. New questions trigger a fresh reading. The cache is kept only in local memory.": "Os resultados só são reutilizados na mesma conversa, pergunta e escopo de permissões. Novas perguntas geram uma nova leitura. O cache fica apenas na memória local.", "Retention days refreshed": "Dias de retenção atualizados", "Retry Interval": "Intervalo entre retries", "Retry settings refreshed": "Configurações de retry atualizadas", "Reuse readings of identical images": "Reutilizar a leitura de imagens idênticas", "Reuse the tool service's vision analysis model": "Reutilizar o modelo de análise visual do serviço de ferramentas", "Reuse the vision configuration for that mode; no separate model list is needed.": "Reutiliza a configuração visual desse modo, sem manter outra lista de modelos.", "Reused within the same session, question and permission scope; asking about new details triggers a fresh read.": "Reutilizado na mesma sessão, pergunta e escopo de permissão; perguntar novos detalhes força nova leitura.", "Revert": "Restaurar", "Reverted to the built-in default prompt": "Revertido para o system prompt padrão integrado", "Revision used to verify the license": "Revisão usada para verificar a licença", "Rotates to the next usable account on every request; a new session goes to whoever is least busy. For spreading usage across accounts instead of letting one carry everything.": "Alterna para a próxima conta utilizável a cada requisição; uma sessão nova vai para quem estiver mais livre. Para distribuir o uso entre as contas em vez de deixar uma carregar tudo.", "Route groups use only their members. Ordinary routes use only accounts and models within their participation scope.": "Grupos de rotas usam apenas seus membros. Rotas comuns usam apenas contas e modelos dentro do escopo de participação.", "Routing": "Roteamento", "Routing settings refreshed": "Configurações de roteamento atualizadas", "Rows whose value equals the default do not count as overrides (only changed keys are stored, not the whole configuration); saving an empty value means this header is not sent, and deleting an edited row reverts it to the default. Changes take effect immediately, no restart needed.": "Linhas com valor igual ao padrão não contam como sobrescrita (o que é armazenado são as “chaves alteradas”, não a configuração completa); salvar com o valor vazio significa que esse cabeçalho não é enviado, e excluir uma linha alterada significa voltar ao valor padrão. As mudanças passam a valer na hora, sem reiniciar.", "Rule / match type": "Regra / tipo de correspondência", "Rule ID: {id}": "ID da regra: {id}", "Rule name": "Nome da regra", "Rule saved for future requests. This historical record was not changed.": "Regra salva para requisições futuras. Este registro histórico não foi alterado.", "Rules ignore case and affect only logs and statistics for new requests, not model selection or permissions.": "As regras ignoram maiúsculas e minúsculas e afetam apenas logs e estatísticas de novas requisições, sem alterar modelos ou permissões.", "Running as": "Forma de execução", "S3-compatible storage": "Armazenamento compatível com S3", "Safari has no install button: tap Share at the bottom, choose \"Add to Home Screen\", then tap \"Add\".": "O Safari não tem botão de instalar: toque em Compartilhar na parte de baixo, escolha \"Adicionar à Tela de Início\" e toque em \"Adicionar\".", "Same-Account Retries": "Retries na mesma conta", "Save & Restart": "Salvar e reiniciar", "Save model override": "Salvar configuração do modelo", "Save raw upstream payloads (request headers, request body, response headers, response body)": "Salvar payloads brutos do upstream (cabeçalhos da requisição, corpo da requisição, cabeçalhos da resposta, corpo da resposta)", "Save settings": "Salvar configurações", "Save the database and required recovery keys in a password-encrypted .a2ab backup. Restore it on Windows, macOS, or Linux without manually copying keys. Restoration replaces accounts, configuration, logs, and desktop settings, and re-encrypts credentials with the destination keys without overwriting them. Exclude logs to reduce file size. Legacy .sql imports remain supported. A safety backup is created before replacement; sign in again afterward.": "Salve o banco e as chaves de recuperação em um backup .a2ab criptografado por senha, restaurável no Windows, macOS ou Linux sem copiar chaves manualmente. A restauração substitui contas, configurações, logs e preferências do desktop, recriptografando as credenciais com as chaves do destino sem sobrescrevê-las. Exclua logs para reduzir o arquivo. A importação de .sql antigo continua disponível. Um backup de segurança é criado antes e é necessário entrar novamente no painel.", "Save the settings before syncing": "Salve as configurações antes de sincronizar", "Saved on the current gateway and displayed publicly on the sign-in page. Does not change the installer, shortcuts, system tray icon or software version information.": "Salvo no gateway atual e exibido publicamente na página de login. Não altera o instalador, os atalhos, o ícone da bandeja do sistema nem as informações de versão.", "Saved; leave blank to keep": "Salvo; deixe em branco para manter", "Saved; leave blank to keep unchanged": "Salva; deixe em branco para manter", "Saving raw upstream payloads:": "Salvando payloads brutos do upstream:", "Saving takes effect on the next restock round, no restart needed. The guard runs inside the app UI: while lightweight mode has destroyed the UI after a window close, no tokens can be minted — requests on the plan-pool (Start Plan) channel land in the request log as 503 (with the reason); reopen the UI and minting recovers automatically.": "Salvar entra em vigor na próxima rodada de reposição, sem reinício. O guardião roda dentro da interface do aplicativo: enquanto o modo leve tiver destruído a interface após fechar a janela, não é possível cunhar tokens — solicitações no canal do pool de planos (Start Plan) caem no registro de solicitações como 503 (com o motivo); reabra a interface e a cunhagem se recupera automaticamente.", "Schema in database": "Schema no banco", "Secret Access Key": "Secret Access Key", "Secret Key": "Chave secreta (Secret Key)", "Security": "Segurança", "Select an available identity header": "Selecione um cabeçalho de identificação disponível", "Select at least one provider": "Selecione pelo menos um provedor", "Select one or more models": "Selecione um ou mais modelos", "Select providers (multiple allowed)": "Selecionar provedores (múltipla seleção)", "Select the client to assign": "Selecione o cliente de destino", "Selected provider": "Provedor selecionado", "Selected providers": "Provedores selecionados", "Selected roles": "Papéis selecionados", "Selection rules": "Regras de seleção", "Self-healing guards": "Proteções de autorrecuperação", "Send original images first; adapt only after an explicit rejection": "Enviar originais primeiro; adaptar somente após rejeição explícita", "Server URL": "Endereço do servidor", "Serves web UI": "Serve a interface web", "Set Endpoint to https://<account ID>.r2.cloudflarestorage.com and Region to auto.": "Defina o Endpoint como https://<ID da conta>.r2.cloudflarestorage.com e a Region como auto.", "Set Endpoint to https://cos.ap-guangzhou.myqcloud.com and Region to ap-guangzhou (change to your actual region).": "Defina o Endpoint como https://cos.ap-guangzhou.myqcloud.com e a Region como ap-guangzhou (ajuste para a sua região).", "Set Endpoint to https://obs.cn-north-4.myhuaweicloud.com and Region to cn-north-4 (change to your actual region).": "Defina o Endpoint como https://obs.cn-north-4.myhuaweicloud.com e a Region como cn-north-4 (ajuste para a sua região).", "Set Endpoint to https://oss-cn-hangzhou.aliyuncs.com and Region to cn-hangzhou (change to your actual region).": "Defina o Endpoint como https://oss-cn-hangzhou.aliyuncs.com e a Region como cn-hangzhou (ajuste para a sua região).", "Set a panel administrator username and password before allowing access from other devices. After registration, network access will be enabled and the app will restart.": "Defina um usuário e uma senha de administrador do painel antes de permitir acesso de outros dispositivos. Após o registro, o acesso pela rede será ativado e o aplicativo será reiniciado.", "Set backup password": "Definir senha do backup", "Set identification rule": "Definir regra de identificação", "Shared settings: {providers}": "Configurações compartilhadas: {providers}", "Show group {name}": "Mostrar grupo {name}", "Show this group": "Mostrar este grupo", "Show {name}": "Mostrar {name}", "Shows the home directory in paths (e.g. C:\\Users\\your-name) as ~ so screenshots do not reveal your username. Only affects this page and its copied text; no files are changed.": "Mostra o diretório pessoal nos caminhos (ex.: C:\\Users\\seu-nome) como ~, para que prints não revelem seu nome de usuário. Afeta apenas esta página e o texto copiado; nenhum arquivo é alterado.", "Shows the home directory in paths as ~ so screenshots do not reveal your username": "Mostra o diretório pessoal nos caminhos como ~, para que prints não revelem seu nome de usuário", "Sidebar menus": "Menus da barra lateral", "Sign Out": "Sair", "Sign in to Agent2API": "Entrar no Agent2API", "Sign in to {name}": "Entrar em {name}", "Sign out of this server only; others are unaffected": "Sai apenas deste servidor; os demais não são afetados", "Sign-in enabled": "Login ativado", "Sign-out failed: {message}": "Falha ao sair: {message}", "Signed in as: {name}": "Conectado como: {name}", "Signed out": "Sessão encerrada", "Simplified Chinese": "chinês simplificado", "Site Key": "Chave do site (Site Key)", "Size of the database's main file (excluding WAL temp files created while running, which are merged back in automatically on exit).": "Tamanho do arquivo principal do banco (não inclui os arquivos temporários WAL em tempo de execução, que já são incorporados automaticamente ao sair).", "Size on Disk": "Tamanho ocupado", "Snapshot bundled with the app (the one from the last release)": "Snapshot embutido no app (o da versão lançada)", "Software version": "Versão do software", "Source code": "Código-fonte", "Source device: {device}": "Dispositivo de origem: {device}", "Source revision": "Revisão de origem", "Stable": "Estável", "Standalone app": "App independente", "Started at": "Iniciado em", "Startup & Tray": "Inicialização e bandeja", "Status code must be an integer from {min} to {max} (received: {text})": "O status code deve ser um número inteiro de {min}–{max} (recebido: {text})", "Status code {code} is already in the list": "O status code {code} já está na lista", "Status polling settings take effect immediately after saving. No tokens are generated automatically. Start required verification in the account’s Plan details. You do not need to keep the interface open when model requests are exempt from verification.": "As configurações de consulta de status entram em vigor após salvar. Nenhum token é gerado automaticamente. Inicie a verificação necessária nos detalhes do plano da conta. Não é preciso manter a interface aberta quando o modelo dispensa verificação.", "Stays within the current route and never jumps to another route group.": "Mantém o escopo da rota atual e não pula para outro grupo de rotas.", "Stock polling interval while Start Plan requests are recent: 2500 ms by default, from 1000 to 30000. Polling slows down when idle and never triggers verification.": "Intervalo de consulta do estoque com solicitações Start Plan recentes: padrão de 2500 ms, entre 1000 e 30000. A frequência diminui quando ocioso e nunca inicia verificação.", "Stock target": "Meta de estoque", "Stop and explain why": "Parar e explicar o motivo", "Storage overview refreshed": "Visão geral do armazenamento atualizada", "Stream Idle Timeout": "Timeout de inatividade do streaming", "Strip keepalive newlines": "Descartar quebras keepalive", "Strip upstream review blacklist fingerprints (rewrite template sentences and headers in request bodies)": "Remover fingerprints da lista de bloqueio da revisão do upstream (reescrever frases de template e cabeçalhos no corpo da requisição)", "Stripping review fingerprints from outbound requests: header key/value pairs are deleted entirely, and template sentences get minimal rewrites.": "Removendo os fingerprints de revisão das requisições de saída: pares chave/valor de cabeçalho excluídos por completo, frases de template com reescrita mínima.", "Submit a Request": "Enviar solicitação", "Supports PNG, JPG and WebP up to 2 MiB and 4096 × 4096 pixels. Images are resized to fit within 512 pixels. Square images are recommended.": "Aceita PNG, JPG e WebP de até 2 MiB e 4096 × 4096 pixels. As imagens são reduzidas para até 512 pixels. Recomendamos imagens quadradas.", "Supports encrypted .a2ab backups and legacy .sql files. Legacy SQL does not include recovery keys, so another machine still needs the original keys.": "Aceita backups .a2ab criptografados e .sql antigos. O SQL antigo não inclui chaves de recuperação; a importação em outra máquina ainda precisa das chaves originais.", "Switch Accounts on Specified Error Codes": "Troca de conta direta em códigos de erro especificados", "Switch models · Vision model answers": "Trocar modelo · O modelo de visão responde", "Switch server": "Trocar de servidor", "Switch to a vision model": "Trocar para um modelo de visão", "Switched automatically to a minimal neutral prompt (an upstream content block — most likely a system-prompt fingerprint false positive); lifts automatically at {until}.": "Mudou automaticamente para um prompt neutro mínimo (bateu num bloqueio de conteúdo do upstream — na maioria das vezes um falso positivo da impressão digital do system); levanta sozinho em {until}.", "Sync accounts, gateway configuration, custom providers, Agent profiles, proxy pool / subscriptions, and check-in and balance records to WebDAV or S3-compatible storage, then pull them back on another machine in one click. Event logs, request details, debug payloads and panel login state are out of scope (they are this machine's runtime traces). Uploaded account credentials stay encrypted; the account key that decrypts them is itself encrypted with the sync password and uploaded alongside — the sync password is never stored in the cloud, so you must re-enter it when restoring on another machine.": "Sincronize contas, configuração do gateway, provedores personalizados, perfis do Agent, pool de proxies / assinaturas e registros de check-in e saldo com WebDAV ou armazenamento compatível com S3, e recupere tudo em outra máquina com um clique. Logs de eventos, detalhes de requisições, pacotes de depuração e o estado de login do painel ficam de fora (são vestígios de execução desta máquina). As credenciais das contas enviadas permanecem criptografadas; a chave que as descriptografa é criptografada com a senha de sincronização e enviada junto — a senha nunca é armazenada na nuvem, então você precisa digitá-la novamente ao restaurar em outra máquina.", "Sync password": "Senha de sincronização", "Synology NAS": "Synology NAS", "System Prompt Mode": "Modo do system prompt", "System events such as sign-ins, account switches, and 429 switches. Range: 1–99999 days.": "Eventos de sistema como login, troca de conta e switch 429. Aceita de 1 a 99999 dias.", "System prompt settings refreshed": "Configurações do system prompt atualizadas", "System · Light · Dark": "Sistema · Claro · Escuro", "Takes effect after a restart; nothing you're doing is interrupted": "Entra em vigor após reiniciar; nada do que você está fazendo é interrompido", "Takes effect immediately after saving, no restart needed; a timeout is treated as an upstream failure (counted in the \"Error\" column of the request logs, and retried according to the \"Request Retries\" settings).": "Passa a valer imediatamente após salvar, sem reiniciar; o timeout é tratado como falha do upstream (contabilizado na coluna “Erro” dos logs de requisições e sujeito às configurações de “Retry de requisições” para nova tentativa).", "Takes effect immediately after saving, no restart needed; if all attempts are exhausted and the request still fails, the error is returned to the client as-is.": "Passa a valer imediatamente após salvar, sem reiniciar; se as tentativas se esgotarem e ainda houver falha, o erro é retornado ao cliente como está.", "Takes effect immediately after saving. Both retention days and record limits apply; lowering either immediately removes excess historical data and cannot be undone.": "Entra em vigor imediatamente após salvar. Os dias de retenção e o limite de registros se aplicam juntos; reduzir qualquer um remove imediatamente os dados históricos excedentes, sem possibilidade de recuperação.", "Takes effect immediately after saving: lowering the retention days deletes the excess historical data at once, and this cannot be undone.": "Passa a valer imediatamente após salvar: reduzir os dias de retenção exclui na hora os dados históricos excedentes, sem possibilidade de recuperação.", "Takes effect immediately after the change, no restart needed (the next request uses the new mode). The fallback is an automatic temporary state; once cleared, this mode's own prompt is restored immediately.": "As mudanças passam a valer na hora, sem reiniciar (a próxima requisição já usa o novo modo). O fallback é um estado temporário automático; depois de encerrado, o prompt próprio deste modo volta imediatamente.", "Takes effect on save, no restart: strategy and stickiness apply to the **next** forwarded request; in-flight requests are unaffected.": "Vale na hora ao salvar, sem reiniciar: estratégia e aderência valem para a escolha da **próxima** requisição encaminhada; requisições em andamento não são afetadas.", "Tap to add a server": "Toque para adicionar um servidor", "Tap to add or switch servers": "Toque para adicionar ou trocar de servidor", "Target path: {path}": "Caminho de destino: {path}", "Tencent Cloud COS": "Tencent Cloud COS", "Test connection": "Testar conexão", "The Cline upstream decides from the request headers whether the caller is one of Cline's own products: X-CLIENT-TYPE: cline-sdk is a hard requirement (without it, free-pool models always return 403), and the version number and platform identifier make the request look closer to the official client. Listed here are the headers the gateway sends by default: editing a row's value overrides the default (you can also add custom headers beyond the default list); saving an empty value means this header is not sent; deleting an edited row in the UI reverts it to the default. Click \"Save\" when done and the next Cline request picks it up immediately. Do not touch a row you do not understand — the value of spoofed headers lies in being word-for-word identical to the official client.": "O upstream da Cline decide pelos cabeçalhos da requisição se o chamador é um produto da própria Cline: X-CLIENT-TYPE: cline-sdk é um requisito obrigatório (sem ele, os modelos do pool gratuito retornam 403 sempre), e o número de versão e o identificador de plataforma aproximam a requisição do formato do cliente oficial. Os cabeçalhos listados aqui são os que o gateway envia por padrão: alterar o valor de uma linha = sobrescrever o padrão (também é possível adicionar cabeçalhos personalizados além da lista padrão); salvar com o valor vazio = esse cabeçalho não é enviado; excluir na interface uma linha alterada = voltar ao padrão. Ao terminar, clique em “Salvar” e a próxima requisição da Cline já usará as mudanças. Se você não entende o significado de uma linha, não a altere — o valor dos cabeçalhos spoofed está em ser idêntico palavra por palavra ao cliente oficial.", "The Share icon sits in the middle of Safari's bottom toolbar": "O ícone de Compartilhar fica no meio da barra inferior do Safari", "The active text comes from {source}{file}. Once saved, this copy overrides the prompt file and the built-in default{note}.": "O texto em vigor no momento vem de {source}{file}. Após salvar, ele prevalece sobre o arquivo de prompt e o padrão integrado{note}.", "The app will restart after saving for this to take effect.": "O aplicativo será reiniciado após salvar para que isso tenha efeito.", "The backend returned no version info": "O backend não retornou informações de versão", "The backup contains recovery keys for account credentials, gateway keys, GitHub tokens, and cloud sync credentials. The whole file is protected by the backup password. Store the file and password separately; without the password, restoration is impossible.": "O backup inclui chaves de recuperação de contas, keys do gateway, tokens do GitHub e credenciais de sincronização. O arquivo inteiro é protegido pela senha do backup. Guarde arquivo e senha separadamente; sem a senha, não é possível restaurar.", "The backup file contains every account credential, the gateway API keys, and the panel admin credentials — enough to log in directly. Keep it safe; do not share it or upload it anywhere public.": "O arquivo de backup contém todas as credenciais de contas, as chaves de API do gateway e as credenciais de administrador do painel — dá para logar com ele diretamente. Guarde com cuidado; não compartilhe nem envie para lugar público.", "The backup password must not exceed 1024 bytes": "A senha do backup não pode exceder 1024 bytes", "The backup passwords do not match": "As senhas do backup não coincidem", "The browser performs the computation locally. No third-party keys or external verification service are required.": "O navegador faz o cálculo localmente. Não exige chaves de terceiros nem serviços externos de verificação.", "The client's system prompt goes out as-is (only fingerprint masking rewrites template sentences).": "O system do cliente é enviado como está (somente o mascaramento de fingerprint reescreve frases de template).", "The client's system prompt goes out as-is.": "O system do cliente é enviado como está.", "The communication style / context management + Environment block.": "O bloco de estilo de comunicação / gestão de contexto + Environment.", "The database and recovery keys are encrypted together. The password is not stored in the application or backup. Keep it safe: without it, restoration is impossible.": "O banco e as chaves são criptografados juntos. A senha não fica no aplicativo nem no backup. Guarde-a com cuidado: sem ela, não é possível restaurar.", "The defaults are usually fine; only tune these when something goes wrong": "Os padrões costumam bastar; ajuste só quando algo der errado", "The display name can contain up to 64 characters": "O nome de exibição pode ter até 64 caracteres", "The entries below open the matching GitHub form in your system's default browser (a GitHub account is required; the template is preset, so just fill it in and submit).": "Os atalhos abaixo abrem o formulário correspondente no GitHub usando o navegador padrão do sistema (é preciso ter uma conta GitHub; o template já vem preenchido, basta completar e enviar).", "The export file contains credentials such as accessToken / refreshToken / apiKey along with custom provider definitions": "O arquivo exportado contém credenciais como accessToken / refreshToken / apiKey e definições de provedores personalizados", "The export file contains credentials such as accessToken / refreshToken / apiKey along with custom provider definitions, and can be used to sign in directly. Keep it safe; do not share it or upload it to a public location.": "O arquivo exportado contém credenciais como accessToken / refreshToken / apiKey e definições de provedores personalizados, e pode ser usado diretamente para login. Guarde-o com cuidado; não o compartilhe nem o envie para locais públicos.", "The gateway endpoints (/v1/*) do not answer browser cross-origin requests by default: a page connecting directly is stopped by the preflight and only reports \"cannot connect to the API\". Note that the allowed origin is * — with no gateway key configured, any web page could use this machine's gateway to hit upstreams, which is why the default is off; if you only use it yourself, serving the page from the same origin as the gateway (a local reverse proxy for /v1) is safer. The panel API (/api/*) is unaffected.": "A API do gateway (/v1/*) não responde por padrão a requisições de outra origem feitas por navegador: a conexão direta da página é barrada no preflight e só mostra “não foi possível conectar à API”. Atenção: a origem é * — sem uma “Chave do gateway” configurada, qualquer página pode usar o gateway local para atingir o upstream; por isso o padrão é desativado. Se for só para você, é mais seguro deixar a página e o gateway na mesma origem (proxy reverso local em /v1). A API do painel (/api/*) não é afetada.", "The gateway is not ready yet": "O gateway ainda não está pronto", "The gateway will listen on all IPv4 interfaces (0.0.0.0). Access is no longer limited to this machine or to the LAN. Public internet access depends on your network and firewall settings.": "O gateway passará a escutar em todas as interfaces IPv4 (0.0.0.0). O acesso não ficará restrito a esta máquina nem à rede local. O acesso pela internet depende das configurações de rede e firewall.", "The gateway will listen only on 127.0.0.1, preventing direct connections from other devices. The web management panel will also be disabled. Existing gateway keys and accounts are not affected.": "Ao desativar, o gateway escutará apenas em 127.0.0.1, impedindo conexões diretas de outros dispositivos. O painel web também será desativado. As chaves do gateway e contas existentes não serão afetadas.", "The heatmap and daily trends on the Reports page. Defaults to 99999 days (about 274 years — kept in full for practical purposes); range 1–99999 days.": "O mapa de calor e as tendências diárias da página de relatórios. Padrão de 99999 dias (retenção praticamente total); aceita de 1 a 99999 dias.", "The interface language is stored only on this machine (localStorage). Switching reloads the whole page immediately and does not affect accounts, keys, or forwarding.": "O idioma da interface fica salvo apenas nesta máquina (localStorage). Após a troca, a página inteira é atualizada na hora; não afeta contas, chaves nem o encaminhamento.", "The local access address is not available yet. Use this machine's IP and gateway port that the other device can reach.": "O endereço de acesso desta máquina ainda não está disponível. Use o IP desta máquina e a porta do gateway que o outro dispositivo consiga alcançar.", "The local account.key is renamed to a backup (account.key.bak-<timestamp>) before importing; it is never deleted.": "Antes de importar, o account.key local é renomeado para backup (account.key.bak-<timestamp>); ele nunca é excluído.", "The logo must not exceed 2 MiB": "O logo não pode exceder 2 MiB", "The long block covering tool usage and environment notes.": "O bloco grande de uso das ferramentas e descrição do ambiente.", "The main process did not return startup settings. Update the desktop app and try again.": "O processo principal não retornou as configurações de inicialização; atualize o aplicativo desktop e tente novamente.", "The match pattern is required and must not exceed {max} characters": "O padrão é obrigatório e deve ter no máximo {max} caracteres", "The mobile app manages accounts, check-in and plugins on the connected gateway and supports sign-in through providers’ declared dynamic methods. Other existing add-account entry points, credential editing and client configuration changes still require the desktop panel.": "O aplicativo móvel gerencia contas, check-in e plugins no gateway conectado e permite login pelos métodos dinâmicos declarados pelos provedores. Outras entradas existentes para adicionar contas, editar credenciais e alterar configurações de clientes ainda exigem o painel desktop.", "The new passwords do not match": "As novas senhas não coincidem", "The newer OpenAI API carries instructions in a developer role instead of system, so conversations sent by current OpenAI SDKs and some clients contain messages with role \"developer\". Many OpenAI-compatible upstreams (especially the passthrough path of custom providers) do not recognize that role and reject the whole request with 400. When enabled, the gateway rewrites developer-role messages to system before every forward — the two roles are equivalent in OpenAI semantics (OpenAI's own migration guide maps them the same way), so the rewrite changes neither content nor meaning, and it is harmless to the built-in upstreams that only accept system anyway. Enabled by default; when off, developer messages go upstream as-is and upstreams that do not know the role return \"unknown role\"-style errors.": "A API mais recente da OpenAI carrega instruções num papel developer em vez de system, então conversas enviadas por SDKs OpenAI atuais e alguns clientes contêm mensagens com role \"developer\". Muitos upstreams compatíveis com OpenAI (especialmente o caminho de passagem dos provedores personalizados) não reconhecem esse papel e rejeitam a solicitação inteira com 400. Quando ativado, o gateway reescreve mensagens do papel developer para system antes de cada encaminhamento — os dois papéis são equivalentes na semântica da OpenAI (o próprio guia de migração da OpenAI faz o mesmo mapeamento), então a reescrita não altera conteúdo nem significado, e é inofensiva aos upstreams integrados que só aceitam system. Ativado por padrão; desativado, as mensagens developer vão para o upstream como estão e upstreams que não conhecem o papel retornam erros do tipo \"papel inexistente\".", "The official text is a single sentence: a declaration that it is ZCode.": "O texto oficial tem apenas uma frase: declara que ele é o ZCode.", "The origin declaration was invalid or unregistered and was ignored.": "A declaração de origem é inválida ou não registrada e foi ignorada.", "The original model answers using the image description": "O modelo original responde com base na descrição", "The original model cannot read images directly": "O modelo original não consegue ler imagens diretamente", "The pattern contains a zero-width space, shown as \\u{200b} in the rule preview. Preserve this character when editing.": "O padrão contém um espaço de largura zero, exibido como \\u{200b} na prévia. Preserve esse caractere ao editar.", "The per-capability source marks in \"Model management\" (upstream / models.dev / overridden) come from this data, and the reasoning-level dropdown in the mapping dialog lists only the levels the model actually accepts, based on it.": "As marcas de origem por capacidade em \"Gerenciamento de modelos\" (upstream / models.dev / substituído) vêm destes dados, e a lista de níveis de raciocínio no diálogo de mapeamento mostra apenas os níveis que o modelo realmente aceita, com base neles.", "The plugin or settings changed. Discard your edits and refresh before editing again.": "O plugin ou as configurações mudaram. Descarte suas alterações e atualize antes de editar novamente.", "The provider is unavailable. Unsaved edits are kept; restore the plugin to continue editing.": "O provedor está indisponível. As edições não salvas foram mantidas; restaure o plugin para continuar editando.", "The provider settings response is invalid. Refresh and try again.": "A resposta das configurações do provedor é inválida. Atualize e tente novamente.", "The remote snapshot uses a different account key but does not include the key file, so it cannot be decrypted here. Re-upload once from the original machine.": "O snapshot remoto usa uma chave de conta diferente, mas não inclui o arquivo de chave, então não pode ser descriptografado aqui. Envie novamente a partir da máquina original.", "The remote snapshot uses a different account key than this machine. Enter the sync password set on the uploading machine to decrypt the key and install it here, then continue the download.": "O snapshot remoto usa uma chave de conta diferente desta máquina. Digite a senha de sincronização definida na máquina que enviou para descriptografar a chave e instalá-la aqui, depois continue o download.", "The request contains identifiers for different applications and was not classified automatically. Use a custom rule to assign it.": "A requisição contém identificadores de aplicativos diferentes e não foi classificada automaticamente. Use uma regra personalizada para atribuí-la.", "The rule list is empty; no fingerprints will be rewritten. Add a rule or restore the defaults.": "A lista está vazia; nenhum fingerprint será alterado. Adicione uma regra ou restaure o padrão.", "The rule name is required and must not exceed {max} characters": "O nome da regra é obrigatório e deve ter no máximo {max} caracteres", "The same provider and model cannot have duplicate overrides": "O mesmo provedor e modelo não podem ter configurações duplicadas", "The same session stays on one account for up to 6 hours; suited to marathon sessions — the upstream context cache gets reused much more.": "A mesma sessão fica na mesma conta por até 6 horas; ideal para sessões longas de horas — o cache de contexto do upstream é aproveitado bem mais.", "The same session tries to stay on one account for 5 minutes; pausing longer than 5 minutes starts a new session. The choice for most cases — fewer account switches in multi-turn chats, without pinning an account.": "A mesma sessão tenta ficar na mesma conta por 5 minutos; pausar mais de 5 minutos conta como sessão nova. A escolha para a maioria dos casos — menos troca de conta em conversas de vários turnos, sem prender uma conta.", "The saved value does not meet the current plugin rules. Edit it or restore the default.": "O valor salvo não atende às regras atuais do plugin. Edite-o ou restaure o padrão.", "The secret key is stored encrypted and never returned to the browser. It is kept when switching back to ALTCHA so you can enable Turnstile again later.": "A chave secreta é armazenada criptografada e nunca é devolvida ao navegador. Ela é mantida ao voltar para ALTCHA para facilitar a reativação.", "The shared vision model changed. Confirm and save again before sending images to the new model.": "O modelo de visão compartilhado mudou. Confirme e salve novamente antes de enviar imagens ao novo modelo.", "The sidebar layout module did not load (ui/sidebar-layout.js must be included before app.js).": "O módulo de layout da barra lateral não foi carregado (ui/sidebar-layout.js deve vir antes de app.js).", "The software identifier exceeded 1 KB and was truncated. Matching uses only the retained portion.": "O identificador excedeu 1 KB e foi truncado. A correspondência usa apenas a parte preservada.", "The text here takes precedence once saved": "Após salvar, este texto passa a valer", "The three data types are timed independently; anything beyond its retention period is deleted: event logs are system events such as sign-ins, account switches, and 429 switches; request logs are the per-request records of everything the gateway forwards upstream; the daily aggregates feed the heatmap and daily trends on the Reports page. Request logs and daily aggregates default to 99999 days (about 274 years — kept in full for practical purposes), and event logs default to 30 days. Lowering a value (for example, 30 days to 7 days) and saving deletes the excess historical data immediately, and this cannot be undone; raising it or leaving it unchanged deletes nothing. All three accept 1–99999 days.": "Os três tipos de dados são contados de forma independente e o que excede o período de retenção é excluído: os logs de eventos são eventos do sistema, como login, troca de conta e switch 429; os logs de requisições são o registro de cada encaminhamento do gateway ao upstream; os agregados diários alimentam o mapa de calor e as tendências diárias da página de relatórios. Logs de requisições e agregados diários têm padrão de 99999 dias (cerca de 274 anos — na prática, retenção total), e os logs de eventos, de 30 dias. Reduzir qualquer um deles (por exemplo, de 30 para 7 dias) e salvar exclui imediatamente os dados históricos excedentes, sem possibilidade de recuperação; aumentar ou manter o valor não exclui nada. Os três aceitam de 1 a 99999 dias.", "The two groups apply to the web panel hosted by the desktop app and the browser panel hosted by Docker / server. Access from other devices depends on network access and firewall settings and is not limited to the LAN. Human verification is enabled by default for both; keeping it enabled is recommended.": "Os dois grupos se aplicam ao painel web hospedado pelo aplicativo desktop e ao painel no navegador hospedado por Docker / servidor. O acesso de outros dispositivos depende das configurações de acesso pela rede e firewall e não se limita à rede local. A verificação humana vem ativada nos dois casos; recomendamos mantê-la ativada.", "The two modes never switch to each other automatically.": "Os dois modos nunca alternam entre si automaticamente.", "The two switches cover the desktop side (the in-app window, including the panel reached from other devices when LAN access is on) and the web side (the browser panel hosted by Docker / server). Both default to on. Turn the desktop one off if you only use it locally and find the check slow; keep the web one on, since that page is exposed to the network.": "Os dois interruptores controlam o lado desktop (a janela do aplicativo, incluindo o painel aberto em outros dispositivos quando o acesso pela LAN está ativo) e o lado web (o painel de navegador hospedado pelo Docker / servidor). Ambos vêm ativados. Desative o do desktop se usar apenas localmente e a verificação incomodar; mantenha o da web ativado, pois aquela página fica exposta à rede.", "The upload contains encrypted account credentials and gateway configuration": "O envio contém credenciais de conta criptografadas e configuração do gateway", "The upstream checks ": "O upstream valida a identidade pela ", "The upstream reviews request bodies by exact word-for-word matching (not semantic review): fixed template sentences injected by the client, billing header field names, and certain bare error codes in the payload cause the entire request to be blocked with 400. With this option on, the gateway rewrites those fingerprints before every forward — header key/value pairs are deleted entirely, and template sentences that carry meaning have a single word swapped (e.g. official CLI for Claude → official CLI tool for Claude); the conversation content and meaning are unaffected. The rule set is built in — there is no word list to maintain, and none can be. With this option off, client templates go upstream as-is and template-sentence false blocks may reappear.": "O upstream revisa o corpo da requisição por “correspondência exata, palavra por palavra” (não é revisão semântica): frases de template fixas injetadas pelo cliente, nomes de campos de cabeçalhos de cobrança e certos códigos de erro soltos, se aparecerem no payload, bloqueiam a requisição inteira com retorno 400. Com esta opção ativada, o gateway reescreve esses fingerprints antes de cada encaminhamento — pares de chave/valor de cabeçalho são removidos por completo e frases de template que carregam significado têm apenas uma palavra trocada (por exemplo, official CLI for Claude → official CLI tool for Claude), sem afetar o conteúdo nem o significado da conversa. O conjunto de regras é integrado; não há lista de palavras a manter, nem seria possível. Com a opção desativada, os templates do cliente vão ao upstream como estão e podem voltar a ocorrer bloqueios indevidos de frases de template.", "The upstream verifies identity by \"structure\": the three blocks must each be a separate block, so they are edited separately here (they cannot be merged into one). Runtime values in the dynamic block are written as placeholders and substituted only when a request is sent: {cwd} working directory, {platform} platform, {shell} shell, {os_version} OS version, {git} whether this is a git repository, {provider} provider identifier, {model} model name. Clearing a block = that block reverts to the official text. A blank line is automatically prepended to the third block when it is sent (the official shape).": "O upstream valida a identidade por “estrutura”: os três blocos precisam ser blocos separados, então os três são editados aqui individualmente (não é possível fundi-los em um só). Valores de execução no bloco dinâmico são escritos como placeholders e substituídos apenas no envio da requisição: {cwd} diretório de trabalho, {platform} plataforma, {shell} shell, {os_version} versão do sistema, {git} se é um repositório git, {provider} identificador do provedor, {model} nome do modelo. Limpar um bloco = aquele bloco volta ao texto oficial. O terceiro bloco é enviado com uma linha em branco na frente (o formato oficial).", "The upstream wait limit for each of the four request stages (seconds, 1–3600): (1) \"Connect Timeout\" = the maximum wait to establish the TCP/TLS connection or proxy tunnel, default 30 seconds; (2) \"Response Headers Timeout\" = the maximum time to wait for the upstream's response headers after the request is sent, default 300 seconds — gateway requests always use stream, and the response headers arrive as soon as the SSE stream is established, regardless of how long the model thinks; (3) \"Stream Idle Timeout\" = the maximum idle gap allowed between adjacent chunks of a streaming response, the timer restarting on each new chunk, default 300 seconds — if the upstream sends no data for a long time, the connection is judged dead and disconnected; (4) \"Non-Streaming Timeout\" = the total budget for reading a complete non-streaming response body (a single timer that is not reset), default 300 seconds. All four are wait limits: as long as data keeps arriving, a normal streaming answer keeps flowing. Changes take effect on the next request without a restart.": "Limites de espera de cada uma das quatro fases da requisição ao upstream (segundos, 1~3600): ① “Timeout de conexão” = espera máxima para estabelecer a conexão TCP/TLS ou o túnel de proxy, padrão 30 segundos; ② “Timeout de espera de resposta” = tempo máximo de espera pelos cabeçalhos de resposta do upstream após o envio da requisição, padrão 300 segundos — as requisições do gateway ao upstream sempre usam stream, e os cabeçalhos de resposta chegam quando o SSE é estabelecido, independentemente de quanto tempo o modelo pense; ③ “Timeout de inatividade do streaming” = inatividade máxima permitida entre dois blocos adjacentes de uma resposta em streaming, com a contagem reiniciada a cada novo dado recebido, padrão 300 segundos — se o upstream ficar muito tempo sem enviar dados, a conexão é considerada travada e é encerrada; ④ “Timeout de resposta não streaming” = orçamento total para ler o corpo inteiro de uma resposta não streaming (contagem única, sem reinício), padrão 300 segundos. Os quatro são limites de espera: enquanto os dados continuarem chegando, uma resposta em streaming normal segue fluindo. Depois de salvar, os valores passam a valer para a próxima requisição, sem reiniciar.", "The vision model answers directly": "O modelo de visão responde diretamente", "The vision model reads the image first, then the original model answers using what was read.": "O modelo de visão lê a imagem primeiro e o modelo original responde usando o que foi lido.", "The vision model reads the images": "O modelo de visão lê as imagens", "The web management panel will no longer be served. You can still manage the gateway in the local desktop app, and API forwarding is not affected.": "O painel web deixará de ser servido. O gerenciamento pelo aplicativo desktop local continuará disponível, e o encaminhamento da API não será afetado.", "The whole request goes to the vision model, which answers directly instead of the original model.": "A requisição inteira vai para o modelo de visão, que responde direto no lugar do modelo original.", "The whole request goes to {model}, which answers directly instead of the original model.": "A requisição inteira vai para {model}, que responde direto no lugar do modelo original.", "Theme": "Modo de exibição", "There are unsaved changes": "Há alterações não salvas", "These icons were obtained through Magpie. The Lobe Icons asset revision was not recorded separately; the revision above was used only to verify the license.": "Os ícones foram obtidos por meio do Magpie. A revisão dos ícones do Lobe Icons não foi registrada separadamente; a revisão acima foi usada apenas para verificar a licença.", "Third-party open-source licenses": "Licenças de código aberto de terceiros", "Third-party reasoning collapse setting refreshed": "Configuração de recolhimento do trabalho de modelos de terceiros atualizada", "This backend does not support editable rules or provider scope. Update the backend and try again.": "Este backend não suporta edição de regras nem escopo de provedores. Atualize o backend e tente novamente.", "This block takes effect once a vision model is chosen.": "Este bloco passa a valer quando um modelo de visão é escolhido.", "This block takes effect once a vision model to answer is chosen.": "Este bloco passa a valer quando um modelo de visão para responder é escolhido.", "This browser is currently signed in to the panel as an administrator. \"Sign Out\" revokes this device's session (automatic renewals within 30 days are voided too) and the account and password must be entered again; other signed-in devices are unaffected.": "Este navegador está conectado a este painel como administrador. “Sair” revoga a sessão de login deste dispositivo (a renovação automática dentro de 30 dias também é invalidada) e será preciso digitar usuário e senha novamente; outros dispositivos já conectados não são afetados.", "This device only": "Somente este dispositivo", "This device's API address": "Endereço da API deste dispositivo", "This environment cannot read version info (bridge method missing)": "Este ambiente não consegue ler as informações de versão (método de ponte ausente)", "This environment does not support LAN access settings": "O ambiente atual não oferece suporte à configuração de acesso LAN", "This gateway does not require bot verification": "Este gateway não exige verificação de bot", "This gateway has no admin account. Access it with an enabled API key.": "Este gateway não tem administrador. Acesse com uma API key ativa.", "This historical request has no saved identification evidence, so it cannot be used to create a rule automatically.": "Esta requisição histórica não tem evidências de identificação salvas e não pode gerar uma regra automaticamente.", "This is the system text the gateway sends in Replace / Append mode.": "Este é o texto do system que o gateway envia nos modos “Substituir / Anexar”.", "This item is hidden": "Este item está oculto", "This item is visible": "Este item está visível", "This list contains the icon source licenses currently recorded in the repository, not a complete inventory of third-party dependencies.": "Esta lista contém as licenças das fontes de ícones atualmente registradas no repositório, não um inventário completo das dependências de terceiros.", "This machine's accounts, gateway configuration, Agent profiles, proxy pool / subscriptions, and check-in and balance records will be replaced by the remote snapshot": "As contas, a configuração do gateway, os perfis do Agent, o pool de proxies / assinaturas e os registros de check-in e saldo desta máquina serão substituídos pelo snapshot remoto", "This machine's business data (accounts, configuration, Agent profiles, proxy pool / subscriptions, check-in and balance records) will be uploaded and": "Os dados de negócio desta máquina (contas, configuração, perfis do Agent, pool de proxies / assinaturas, registros de check-in e saldo) serão enviados e", "This model only reads the image; the original model still answers.": "Este modelo apenas lê a imagem; quem responde continua sendo o modelo original.", "This model receives the images and the conversation and produces this answer itself.": "Este modelo recebe as imagens e a conversa e produz esta resposta.", "This project's AGPL-3.0 license does not replace these third-party licenses. Trademark rights in names and logos belong to their respective owners.": "A licença AGPL-3.0 deste projeto não substitui estas licenças de terceiros. Os direitos de marca sobre nomes e logotipos pertencem aos respectivos titulares.", "This provider has no editable settings": "Este provedor não tem configurações editáveis", "This restores the default groups, order and visibility. Groups you created are removed (their menus are kept).": "Restaura os grupos, a ordem e a visibilidade padrão. Grupos criados por você são removidos (os menus são mantidos).", "This rule was deleted. Close the editor and add it again.": "Esta regra foi excluída. Feche o editor e adicione-a novamente.", "This rule was not used. Check its switch, caller declarations, or rule order.": "Esta regra não foi usada. Verifique a ativação, as declarações de origem ou a ordem das regras.", "This software comes without warranty and may be modified and distributed under AGPL-3.0. Modified network services must offer their Corresponding Source to users.": "Este software não oferece garantia e pode ser modificado e distribuído sob AGPL-3.0. Serviços de rede modificados devem oferecer aos usuários o código-fonte correspondente.", "This version does not support brand settings": "Esta versão não oferece suporte às configurações da marca", "Three separate blocks, edited separately": "Os três blocos são separados, por isso a edição é individual", "Timeout": "Timeout", "Timeout settings refreshed": "Configurações de timeout atualizadas", "To go back to the previous one, clear this and save (the file path you configured is not deleted).": "Para voltar ao texto anterior, basta limpar este campo e salvar (o caminho de arquivo que você configurou não é apagado).", "Token Readout Scale": "Escala de leitura de Token", "Total requests": "Requisições totais", "Total size of the database main file and WAL file, using the same calculation as the request cleanup dialog. After clearing data, vacuum the database to reclaim unused space.": "Tamanho total do arquivo principal do banco e do arquivo WAL, usando o mesmo cálculo do diálogo de limpeza de requisições. Após a limpeza, compacte o banco para recuperar o espaço livre.", "Totals cover the whole group (default): filtering and search do not change them, and filtered-out or disabled accounts still count.": "O total abrange o grupo inteiro (padrão): filtros e busca não o alteram, e contas filtradas ou desativadas ainda contam.", "Totals only add up accounts visible under the current filter; changing the filter or search changes the number.": "O total soma apenas as contas visíveis no filtro atual; mudar o filtro ou a busca altera o número.", "Traditional Chinese": "chinês tradicional", "Tried in order when the first choice is unavailable; leave empty to stop and explain why.": "Tentados em ordem quando a primeira opção não estiver disponível; vazio significa parar e explicar o motivo.", "Trigger threshold": "Limite de acionamento", "Trips this account off entirely after consecutive failures reach a threshold (off by default). Division of labor with failure backoff: backoff means \"let a single failure cool off\" — light penalty, automatic recovery; the circuit breaker means \"this account is misbehaving as a whole, stop trying it one request at a time\" and takes several consecutive successes to close. While open, the account is skipped — unless it is the only one left, in which case it still gets one try.": "Desliga esta conta por inteiro depois que as falhas consecutivas atingem um limiar (desligado por padrão). Divisão de papéis com o recuo por falha: o recuo cuida de \"deixar uma falha única esfriar\" — penalidade leve, recuperação automática; o disjuntor cuida de \"esta conta está ruim como um todo, pare de tentar uma a uma\" e só fecha após vários sucessos consecutivos. Enquanto aberto, a conta é pulada — a menos que seja a única restante; nesse caso ela ainda recebe uma tentativa.", "Truncated": "Truncado", "Try designated fallbacks in order": "Tentar alternativas na ordem definida", "Turned off the gateway-provided prompt for \"{label}\": whether it passes upstream validation depends on the upstream's current criteria": "System prompt interno do gateway de “{label}” desativado: se ele passa na validação do upstream depende dos critérios atuais do upstream", "Two display preferences for the accounts table. They are stored only on this machine (localStorage) and never affect account data or forwarding. \"Only sum accounts visible under the current filter\": each provider band on the accounts page shows a \"Total available\" badge, and by default it sums the whole group — filtering and search do not change it, and accounts filtered out still count (balance is an asset; disabling an account only keeps it out of forwarding, the credit stays). Turn this on to add up only the rows currently visible: filter down to one account with 100 credits and the total reads 100, not 1,000 (the sum of two accounts in that group). Paging does not take part in this rule — pages are just different screens of the same result, so the total does not change as you flip pages. \"Hide account names\" is the same switch as the eye next to the \"Account\" column header: when on, names in the account column are shown as asterisks, handy for screenshots.": "Duas preferências de exibição da tabela de contas. Ficam apenas nesta máquina (localStorage) e não afetam dados de conta nem o encaminhamento. \"Somar apenas as contas visíveis no filtro atual\": cada faixa de provedor na página de contas mostra um selo \"Total disponível\" e, por padrão, ele soma o grupo inteiro — filtros e busca não o alteram, e contas filtradas ainda contam (saldo é ativo; desativar apenas mantém a conta fora do encaminhamento, o crédito permanece). Ative para somar apenas as linhas visíveis: filtre até uma conta com 100 créditos e o total mostra 100, não 1.000 (a soma das duas contas do grupo). A paginação não participa desta regra — páginas são apenas telas diferentes do mesmo resultado, então o total não muda ao virar páginas. \"Ocultar nomes das contas\" é o mesmo botão do olho ao lado do cabeçalho \"Conta\": quando ativado, os nomes na coluna de contas aparecem como asteriscos, útil para capturas de tela.", "Unavailable": "Indisponível", "Unchecked, only business data is backed up (accounts, configuration, balance records) and the file shrinks considerably; event logs, request stats, and debug payloads are left out.": "Desmarcado, só os dados de negócio entram no backup (contas, configuração e registros de saldo) e o arquivo fica bem menor; logs de eventos, estatísticas de requisições e payloads de depuração ficam de fora.", "Unknown account": "Conta desconhecida", "Unknown device": "Dispositivo desconhecido", "Unknown reason": "Motivo desconhecido", "Unknown source": "Origem desconhecida", "Unregistered gate": "Bloqueio de não registrado", "Unsaved": "Não salvo", "Unsaved changes: save first to sync (testing the connection is unaffected).": "Alterações não salvas: salve antes de sincronizar (o teste de conexão não é afetado).", "Up to 64 characters. Leave blank to restore Agent2API.": "Até 64 caracteres. Deixe em branco para restaurar Agent2API.", "Update": "Atualizar", "Update channel": "Canal de atualização", "Update egress route": "Rota de saída da atualização", "Updating online": "Atualizando online", "Upload": "Enviar", "Upload failed: {message}": "Falha no envio: {message}", "Upload logo": "Enviar logo", "Upload only when account data, settings, check-in results or balances change. Changes to export or query timestamps alone do not trigger an upload.": "O upload só ocorre quando há mudanças reais nas contas, configurações, resultados de check-in ou saldos. Alterações apenas nos horários de exportação ou consulta não geram uploads.", "Upload to cloud": "Enviar para a nuvem", "Uploading…": "Enviando…", "Upstream CLI version": "Versão da CLI upstream", "Upstream client version": "Versão do cliente upstream", "Upstream debug payloads": "Payloads de depuração do upstream", "Upstream not configured": "Upstream não configurado", "Uptime": "Tempo de atividade", "Use \"Add to Home Screen\" in the browser menu to install this page as an app: full screen, no address bar, just like a native app.": "Use \"Adicionar à Tela de Início\" no menu do navegador para instalar esta página como app: tela cheia, sem barra de endereço, igual a um app nativo.", "Use Chinese units (yi / wan)": "Usar unidades chinesas (yi / wan)", "Use an address reachable from the connecting device. The local address shown here does not imply public internet reachability.": "Use um endereço alcançável pelo dispositivo que vai se conectar. O endereço local exibido aqui não garante acesso pela internet.", "Use at least 12 characters; a long, unique password is recommended": "Use ao menos 12 caracteres; recomendamos uma senha longa e exclusiva", "Use local magnitude words (万 / 亿-style)": "Usar magnitudes locais (estilo k / M)", "Used by every provider that is not configured individually": "Todos os provedores sem configuração individual usam esta", "Used to encrypt the account key that goes to the cloud. Remember it — it is not stored in the cloud, and you must enter the same password when restoring on another machine, otherwise the account data cannot be decrypted.": "Usada para criptografar a chave da conta enviada à nuvem. Memorize-a — ela não é armazenada na nuvem e você precisa digitar a mesma senha ao restaurar em outra máquina, caso contrário os dados das contas não poderão ser descriptografados.", "Used when the model catalog does not say whether images are supported.": "Usado quando o catálogo não informa se o modelo aceita imagens.", "Uses Rust regular expression syntax, validated by the backend when saving. Lookaround and backreferences are not supported.": "Usa a sintaxe de expressões regulares do Rust, validada pelo backend ao salvar. Lookaround e referências anteriores não são suportados.", "Uses this rule": "Usa esta regra", "Using defaults": "Usando os padrões", "Using existing data only, no online refresh": "Usando apenas os dados existentes, sem atualização online", "Usually a network issue — tap Retry on the right": "Normalmente é um problema de rede — toque em Repetir", "Value": "Valor", "Value (empty = not sent)": "Valor (vazio = não enviar)", "Verbose logs": "Logs detalhados", "Verification is provided by Cloudflare. Both the browser and gateway must be able to reach Cloudflare. Failed verification or an unavailable service will not allow access.": "A verificação é fornecida pela Cloudflare. O navegador e o gateway precisam acessar a Cloudflare. Uma falha na verificação ou indisponibilidade do serviço não libera o acesso.", "Verification method": "Método de verificação", "Version": "Versão", "Version info": "Informações de versão", "Version info has not been loaded yet": "As informações de versão ainda não foram carregadas", "Version info · connected gateway": "Informações de versão · gateway conectado", "View and adjust provider-specific options": "Veja e ajuste opções específicas de cada provedor", "View built-in clients ({n})": "Ver clientes integrados ({n})", "Vision model": "Modelo de visão", "Vision model from the tool service (not configured)": "Modelo de visão do serviço de ferramentas (não configurado)", "Vision model source": "Origem do modelo de visão", "Vision model switching settings": "Configuração de troca de modelo de visão", "Wait time between two retries, shared by both settings. Range: 0–300 seconds.": "Tempo de espera entre duas tentativas, compartilhado pelas duas opções; valores de 0–300 segundos.", "Web": "Web", "Web management address": "Endereço do painel web", "Web sign-in / registration verification": "Verificação de login / cadastro na web", "Web: sign-in / registration requires ALTCHA proof-of-work": "Web: login / registro exige verificação ALTCHA", "Web: sign-in / registration requires ALTCHA proof-of-work (in use now)": "Web: login / registro exige verificação ALTCHA (em uso agora)", "WebView / browser engine": "WebView / motor do navegador", "What actually happens: ": "O que acontece na prática: ", "When a model cannot read images, use your selected mode. Native image-capable requests pass through without an extra vision call.": "Quando o modelo não puder ler imagens, use o modo escolhido. Solicitações a modelos com suporte nativo seguem diretamente, sem uma chamada visual extra.", "When enabled, callers can declare a registered client name using the dedicated header. This is not authentication: it only affects logs and statistics and grants no additional permissions.": "Quando ativado, o solicitante pode declarar um cliente registrado pelo cabeçalho dedicado. Isso não autentica a identidade: afeta apenas logs e estatísticas, sem conceder permissões adicionais.", "When enabled, closing the window destroys the interface and releases WebView processes. Forwarding, scheduled check-ins and balance queries continue in the background. ZCode requests exempt from verification are unaffected. If verification is required, reopen the interface and complete it in the account’s Plan details. This setting applies only when closing minimizes the app to the tray.": "Quando habilitado, fechar a janela libera a interface e os processos WebView. Encaminhamento, check-ins agendados e consultas de saldo continuam em segundo plano. Solicitações ZCode sem verificação não são afetadas. Quando exigida, reabra a interface e conclua a verificação nos detalhes do plano da conta. Aplica-se somente quando fechar minimiza o aplicativo para a bandeja.", "When enabled, closing the window does not just hide it — the entire UI window is destroyed: the six resident WebView2 processes (about 200 MB of memory) exit, while gateway forwarding, scheduled check-ins and balance queries keep running in the background process, unaffected; click the tray icon to reopen the UI when needed (WebView cold start takes about 1 second). Note: while the UI is destroyed, CAPTCHA tokens for the ZCode \"Plan pool (Start Plan)\" channel are minted by the UI and cannot be replenished — requests on that channel land in the request log as 503 (with the reason), and reopening the UI restores minting automatically. This switch only matters when \"Minimize to tray on close\" is enabled; minimizing the window is unaffected.": "Quando ativado, fechar a janela não apenas a esconde — toda a janela da interface é destruída: os seis processos residentes do WebView2 (cerca de 200 MB de memória) saem, enquanto o encaminhamento do gateway, os check-ins agendados e as consultas de saldo continuam no processo de segundo plano, sem impacto; clique no ícone da bandeja para reabrir a interface quando necessário (o arranque a frio do WebView leva cerca de 1 segundo). Nota: enquanto a interface estiver destruída, os tokens de CAPTCHA do canal \"Pool de planos (Start Plan)\" do ZCode são cunhados pela interface e não podem ser repostos — solicitações nesse canal caem no registro como 503 (com o motivo), e reabrir a interface restaura a cunhagem automaticamente. Este interruptor só importa quando \"Minimizar para a bandeja ao fechar\" estiver ativado; minimizar a janela não é afetado.", "When forwarding a request to an upstream fails (transient server errors, connection failures, and WorkBuddy's 11-128 sensitive-word blocking), the gateway waits for an interval and sends it once more. The counts come in two tiers covering two different things: (1) \"Same-Account Retries\" resends in place on the same account a few times — usually the prompt was blocked by the upstream or the link flickered, and resending after a wait tends to succeed; (2) \"Account-Switch Retries\" is how many more accounts this request may try — the account that sent it first does not count, each switch costs one, regardless of whether it is the same provider (switching to the next account of the same provider also counts), and when the switches are exhausted and it still fails, the error is returned to the client. Setting both to 0 means no retries on failure — error out immediately. Note that account-level throttling (429) does not consume these account switches — that kind of failure goes through the \"cool down the account and move to the next one\" fallback, a separate path from the retries here. There is also the \"Switch Accounts on Specified Error Codes\" list (default 402): upstream status codes on the list are not retried on the same account; the gateway switches to the next account in the queue and keeps trying (the switch also consumes an \"Account-Switch Retries\" slot), and only when those are exhausted is the error returned to the client.": "Quando o encaminhamento ao upstream falha (erro momentâneo do servidor, falha de conexão e bloqueio por palavra sensível 11-128 do WorkBuddy), o gateway espera um intervalo e envia de novo. As tentativas se dividem em duas opções, que tratam de duas coisas: ① “Retries na mesma conta” — quantas vezes reenviar na própria conta; normalmente é o prompt bloqueado pelo upstream ou uma oscilação momentânea do link, e reenviar depois de um tempo costuma resolver; ② “Retries trocando de conta” — por quantas contas a mais esta requisição pode tentar; a conta do primeiro envio não conta, cada troca desconta uma, independentemente de ser o mesmo provedor (trocar para a conta seguinte do mesmo provedor também conta), e se o limite se esgotar com falha, o erro é retornado ao cliente. Definir ambas como 0 significa não tentar de novo em caso de falha e retornar o erro direto. Atenção: o limite no nível da conta (429) não consome as trocas de conta daqui — esse tipo de falha segue o fallback de “esfriar a conta e passar para a próxima”, um caminho diferente do retry daqui. Existe ainda a lista de “Troca de conta direta em códigos de erro especificados” (padrão 402): falhas que correspondem aos status codes do upstream da lista não são reenviadas na mesma conta — o gateway passa direto para a próxima conta da fila e continua tentando (a troca também consome “Retries trocando de conta”), e só quando elas se esgotam com falha é que o erro é retornado ao cliente.", "When image capability is unknown": "Quando o suporte a imagens for desconhecido", "When no vision model is available": "Quando não houver modelo de visão disponível", "When off, manual upload/download is rejected too.": "Quando desativado, envio/download manual também é recusado.", "When on, the gateway stores every forward's **request to the upstream** (headers + body) and the **upstream response** (status code + headers + body) locally in full, for the \"Details\" view on the request logs page. Credential fields in request headers — Authorization, Cookie, API Key, and the like — are always replaced with [redacted] and never hit the disk in plain text; request and response bodies are stored as-is (they may contain your conversations). Only the most recent 500 payloads are kept; the oldest are dropped beyond that. This is a temporary troubleshooting switch — keep it off when you don't need it.": "Quando ligado, o gateway salva localmente, por inteiro, **a requisição enviada ao upstream** (cabeçalhos + corpo) e **a resposta do upstream** (código de status + cabeçalhos + corpo) de cada encaminhamento, para a visualização em \"Detalhes\" na página de logs de requisições. Campos de credenciais nos cabeçalhos — Authorization, Cookie, API Key e afins — são sempre trocados por [redacted] e nunca tocam o disco em texto puro; corpos de requisição e resposta ficam como estão (podem conter suas conversas). Só os 500 payloads mais recentes ficam guardados; os mais antigos são descartados. É um interruptor temporário para diagnóstico — mantenha desligado quando não precisar.", "When on, the login page solves the challenge in the background (invisible to humans) while every scripted attempt must compute one first — brute force and account squatting become far more expensive. It only affects panel sign-in / registration, not API keys used by clients. Desktop and web are independent: the desktop page mostly serves this machine and the LAN, while the web page (Docker / server) is exposed to the network and benefits more from staying on.": "Quando ativado, a página de login resolve o desafio em segundo plano (invisível para pessoas), enquanto cada tentativa automatizada precisa calcular um antes — força bruta e registro indevido ficam bem mais caros. Afeta apenas o login / registro do painel, não as API keys dos clientes. Desktop e web são independentes: o desktop atende principalmente esta máquina e a LAN, enquanto o web (Docker / servidor) fica exposto à rede e se beneficia mais de permanecer ativado.", "When something goes wrong, screenshot this page or use \"Copy all info\" and paste the text into your report — that is usually enough to narrow down the cause.": "Quando algo der errado, tire um print desta página ou use \"Copiar todas as informações\" e cole o texto no relato — normalmente isso já basta para identificar a causa.", "When these models see an image, the vision model from the tool service reads it first, and they answer using what was read.": "Quando esses modelos recebem uma imagem, o modelo de visão do serviço de ferramentas a lê primeiro, e eles respondem com base no que foi lido.", "When these models see an image, {model} reads it first, and they answer using what was read.": "Quando esses modelos recebem uma imagem, {model} a lê primeiro, e eles respondem com base no que foi lido.", "Which model reads the image": "Qual modelo lê a imagem", "Which models use this way": "Quais modelos usam esta forma", "Which prompt to use is decided per upstream, so each provider can have its own mode, prompt file, and text: providers not listed here all use the default settings above, and \"Follow Default\" removes a provider's override and returns it to the default. Providers with a \"Gateway-Provided Prompt\" row (currently the two ZCode providers) are listed here by default — that text is installed by the gateway itself, comes from neither the client nor a prompt file, is on by default, can be turned off, and its text can be edited (edited blocks use your text); whether it still passes upstream validation after being turned off depends on the upstream's current criteria, and the row's hint documents what was measured. \"Mode / Prompt File / Prompt Text\" controls how the client's own system prompt is handled — a separate matter from that switch.": "Qual prompt usar é uma decisão tomada por upstream, então cada provedor pode ter seu próprio modo, arquivo de prompt e texto: provedores não listados aqui seguem a configuração padrão acima, e “Seguir padrão” remove a configuração individual desse provedor, voltando ao padrão. Os provedores com a linha “Interno do gateway” (atualmente os dois da ZCode) já aparecem aqui por padrão — esse trecho é um texto instalado pelo próprio gateway, que não vem do cliente nem de um arquivo de prompt, fica ativado por padrão, pode ser desativado e também pode ter o texto editado (os trechos editados usam o seu texto); se ele ainda passa na validação do upstream depois de desativado depende dos critérios atuais do upstream, e a própria linha documenta a base dos testes. “Modo / arquivo de prompt / texto” trata de como o system do próprio cliente é processado — é uma coisa separada daquele switch.", "While this mode is on, its own prompt is not sent; lift it as soon as your prompt is fixed.": "Enquanto este modo estiver ativo, o prompt próprio dele não é enviado; levante assim que ajustar o seu prompt.", "While waiting, the status column in the request logs shows a \"Queueing\" phase, and the \"Internal Retries\" section of the detail dialog lists each wait duration; when the waits run out, HTTP 503 is returned (not 401/429: credentials are not refreshed and the account is not marked as rate-limited).": "Durante a espera, a coluna de status dos logs de requisições mostra a fase “Na fila”, e o diálogo de detalhes, em “Retries internos”, mostra a duração de cada espera uma a uma; quando as esperas se esgotam, é retornado HTTP 503 (não 401/429: nem atualiza credenciais, nem marca a conta como limitada).", "Windows installer (NSIS)": "Instalador do Windows (NSIS)", "Windows service": "Serviço do Windows", "Your changes are still saved locally. After fixing the network or credentials, the next change retries automatically, or click \"Upload to cloud\" manually.": "Suas alterações continuam salvas localmente. Depois de corrigir a rede ou as credenciais, a próxima alteração tenta de novo automaticamente, ou clique em \"Enviar para a nuvem\".", "Your changes remain saved locally. The system will retry automatically with a longer delay. After fixing the network or credentials, you can also select \"Upload to cloud\" manually.": "As alterações continuam salvas neste dispositivo. O sistema tentará novamente automaticamente após uma espera maior. Depois de corrigir a rede ou as credenciais, você também pode clicar em “Enviar para a nuvem” manualmente.", "Your previous \"global mode + per-model overrides\" has been filled into the model lists below with the same meaning. Keep it as is or adjust it; once you change anything it is stored in the new form.": "O seu antigo \"modo global + ajustes por modelo\" foi preenchido nas listas de modelos abaixo com o mesmo significado. Use como está ou ajuste; ao alterar qualquer coisa, passa a ser gravado no novo formato.", "ZCode upstream settings determine whether model requests need verification, independently of plan claims. The background only checks settings and stock; it never runs verification or opens a puzzle automatically. Start required verification in the account’s Plan details. Tokens are single-use, expire shortly, and are not retried automatically after failure or cancellation.": "As configurações do provedor ZCode determinam se o modelo exige verificação, separadamente do resgate de planos. O processo em segundo plano só consulta configurações e estoque; nunca executa verificação nem abre um quebra-cabeça automaticamente. Inicie-a nos detalhes do plano da conta. Tokens são de uso único, expiram rapidamente e não são repetidos após falha ou cancelamento.", "Zoom Level": "Nível de zoom", "Zoom the whole interface in or out (text and controls scale together), equivalent to Ctrl +/- in a browser: 11 steps, applied immediately and remembered.": "Amplia ou reduz a interface inteira (texto e controles juntos), com o mesmo efeito de Ctrl +/- no navegador: 11 níveis; a mudança vale na hora e é memorizada.", "Zoom the whole interface proportionally (text, controls, and spacing scale together), equivalent to Ctrl +/- in a browser: 80%–130% in 5% steps. The window itself does not resize — what changes is the page content's display scale; the setting applies immediately and is remembered, so the next launch opens at this scale. The larger the scale, the less you can see at once; with a narrow window or wide tables, do not set it too high.": "Amplia ou reduz a interface inteira proporcionalmente (texto, controles e espaçamentos juntos), com o mesmo efeito de Ctrl +/- no navegador: 80%–130%, em passos de 5%. A janela em si não é redimensionada; o que muda é a proporção de exibição do conteúdo da página. A configuração vale imediatamente e é memorizada, e a próxima inicialização já abre nesta proporção. Quanto maior o zoom, menor a área visível; com janelas estreitas ou tabelas largas, não é recomendável aumentá-lo demais.", "a built-in assembly": "um conjunto integrado", "agent2api.db in the configuration directory (it holds accounts, logs, request records, debug payloads, and settings).": "O agent2api.db no diretório de configuração (contas, logs, registros de requisições, payloads de debug e configurações ficam todos nele).", "approx. {n} characters": "cerca de {n} caracteres", "days": "dias", "failed: {n}": "Falhas: {n}", "for identity: the three blocks must each be a separate block placed at the very top (measured: merging the three into one returns 405 / 3012). So they are edited per block here; they cannot be merged into one. Edited blocks use your text; unedited blocks keep the official text; clearing a block reverts that block to the official text.": ": os três blocos precisam vir no início, cada um como um bloco separado (testado: três blocos fundidos em um só retornam 405 / 3012). Por isso a edição aqui é por bloco — não é possível fundi-los. Blocos alterados usam o seu texto; os não alterados continuam com o texto oficial; limpar um bloco = aquele bloco volta ao texto oficial.", "iOS app": "Aplicativo iOS", "models.dev is an open-source, community-maintained model database. It fills in what the upstream never told us: context window, max output, tool calling, images, video, reasoning support, and which reasoning levels the model actually accepts. Priority: values you edited by hand under \"Model capabilities\" > what the upstream catalog declares > models.dev — it only fills gaps the upstream left, and never overrides a declared value. A snapshot ships inside the app, so offline, first-run and blocked-network cases still have data; while enabled it refreshes online on the \"Model catalog refresh\" schedule (in the same round, or on demand here). Turning it off only stops the online refresh; existing data stays in use.": "O models.dev é um banco de dados de modelos aberto e mantido pela comunidade. Ele preenche o que o upstream não informa: janela de contexto, saída máxima, chamada de ferramentas, imagem, vídeo, suporte a raciocínio e quais níveis de raciocínio o modelo realmente aceita. Prioridade: valores que você editou em \"Capacidades do modelo\" > o que o catálogo do upstream declara > models.dev — ele só preenche lacunas deixadas pelo upstream e nunca sobrepõe um valor declarado. Um snapshot vem embutido no app, então offline, primeira execução e rede bloqueada continuam tendo dados; quando ativado, atualiza online no intervalo da tarefa \"Atualização do catálogo de modelos\" (na mesma rodada, ou sob demanda aqui). Desativar apenas interrompe a atualização online; os dados já obtidos continuam em uso.", "models.dev metadata": "Metadados models.dev", "models.dev metadata updated ({count} entries)": "Metadados do models.dev atualizados ({count} entradas)", "models.dev model metadata": "Metadados de modelos do models.dev", "ms": "ms", "overwrite": "sobrescrever", "panel admin account": "conta de administrador do painel", "px": "px", "skipped: {n}": "Ignorados: {n}", "structure ": "estrutura", "systemd service": "Serviço systemd", "the built-in default prompt": "System prompt padrão integrado", "the old snapshot at the same remote path. Event logs, request details and debug payloads are not uploaded.": "o snapshot antigo no mesmo caminho remoto. Logs de eventos, detalhes de requisições e pacotes de depuração não são enviados.", "the text edited in the UI": "Texto editado na interface", "times": "vezes", "wholesale-replaced": "substituídos por inteiro", "{added} added, {updated} updated{suffix}{note}": "{added} adicionadas, {updated} atualizadas{suffix}{note}", "{count} / {limit} payloads saved (oldest discarded when the limit is exceeded).": "{count} / {limit} payloads salvos (os mais antigos são descartados quando o limite é excedido).", "{count} entries": "{count} entradas", "{count} entries · from {origin}{at} · {mode}": "{count} entradas · de {origin}{at} · {mode}", "{count} rules enabled, applied to {scope}.": "{count} regras ativadas, aplicadas a {scope}.", "{count} rules, executed in list order": "{count} regras, executadas na ordem da lista", "{d}d {h}h": "{d}d {h}h", "{h}h {m}m": "{h}h {m}min", "{label} ({message})": "{label} ({message})", "{label} prompt file": "Arquivo de prompt de {label}", "{label} prompt mode": "Modo de prompt de {label}", "{lines} lines, {chars} characters (based on the current draft)": "{lines} linhas, {chars} caracteres (com base no rascunho atual)", "{minutes} minutes": "{minutes} minutos", "{models} appears in both blocks and will be handled by assisted image reading. To change that, remove it from one of the model lists.": "{models} aparece nos dois blocos e será tratado por leitura assistida de imagem. Para mudar isso, remova-o de uma das listas.", "{mode} in effect: the system prompt sent upstream comes from {source}{lines}.": "Modo {mode} ativo: o system enviado ao upstream vem de {source}{lines}.", "{m}m": "{m}min", "{noun} cannot be empty (allowed range: {min}–{max})": "{noun}: não pode ficar em branco (valores aceitos: {min}–{max})", "{noun} must be an integer": "{noun}: deve ser um número inteiro", "{noun} must be between {min} and {max} (currently entered: {text})": "{noun}: deve estar entre {min} e {max} (valor atual: {text})", "{n} B": "{n} B", "{n} GB": "{n} GB", "{n} KB": "{n} KB", "{n} MB": "{n} MB", "{n} headers will be sent with every Cline request": "{n} cabeçalhos serão enviados em cada requisição da Cline", "{n} items · {shown} shown": "{n} itens · {shown} visíveis", "{n} servers · tap to switch": "{n} servidores · toque para trocar", "{total} menus · {shown} shown · {hidden} hidden · {groups} groups": "{total} menus · {shown} visíveis · {hidden} ocultos · {groups} grupos", "⚠️ Bot check disabled for \"{label}\"": "⚠️ Verificação de bot desativada para \"{label}\"", "⚠️ Captcha disabled": "⚠️ Captcha desativado", "⚠️ Key warning": "⚠️ Aviso de chaves", "✅ Account key imported; continue with the download": "✅ Chave da conta importada; continue o download", "✅ Automatically created the gateway key \"Default\" (view it on the \"Gateway Key\" page)": "✅ Chave do gateway “Padrão” criada automaticamente (veja na página “Chave do gateway”)", "✅ Backed up {n} tables ({size}) to {file}": "✅ {n} tabelas ({size}) backupadas em {file}", "✅ Bot check enabled for \"{label}\"": "✅ Verificação de bot ativada para \"{label}\"", "✅ Captcha enabled": "✅ Captcha ativado", "✅ Cline spoofed headers saved": "✅ Cabeçalhos spoofed do Cline salvos", "✅ Cloud sync settings saved": "✅ Configurações de sincronização na nuvem salvas", "✅ Collapse third-party model work after the answer enabled": "✅ Recolhimento automático do trabalho de modelos de terceiros após a resposta ativado", "✅ Connected: {path}": "✅ Conectado: {path}", "✅ Content-block fallback cleared": "✅ Fallback de bloqueio de conteúdo removido", "✅ Debug mode disabled": "✅ Modo debug desativado", "✅ Debug mode enabled": "✅ Modo debug ativado", "✅ Developer role compatibility enabled": "✅ Compatibilidade com papel developer ativada", "✅ Encrypted backup of {n} tables ({size}), including recovery keys: {file}": "✅ Backup criptografado de {n} tabelas ({size}), com chaves de recuperação: {file}", "✅ Exported {count} accounts{note}{file}": "✅ {count} contas exportadas{note}{file}", "✅ Fingerprint masking enabled": "✅ Mascaramento de fingerprint de saída ativado", "✅ Fingerprint masking settings saved": "✅ Configurações de mascaramento salvas", "✅ Gateway-provided prompt installed for \"{label}\"": "✅ System prompt interno do gateway instalado para “{label}”", "✅ Image compression is on": "✅ Compressão de imagens ativada", "✅ Import complete: {summary}": "✅ Importação concluída: {summary}", "✅ Kept for {days} days": "✅ Retenção definida para {days} dias", "✅ Kept for {days} days; older data cleared": "✅ Retenção definida para {days} dias; o excedente foi removido", "✅ Now using k / M / B abbreviations": "✅ Agora usando abreviações k / M / B", "✅ Now using local magnitude words (万 / 亿-style)": "✅ Agora usando magnitudes locais (k / M)", "✅ Password changed. Sign-ins on other devices have been revoked": "✅ Senha alterada. Os acessos em outros dispositivos foram revogados", "✅ Record limit set to {count}": "✅ Limite definido para {count} registros", "✅ Record limit set to {count}; excess records removed": "✅ Limite definido para {count} registros; excedentes removidos", "✅ Restored from the cloud{note}": "✅ Restaurado da nuvem{note}", "✅ Restored {n} tables{note}": "✅ {n} tabelas restauradas{note}", "✅ Routing settings saved": "Configurações de roteamento salvas", "✅ Saved: Switch Accounts on Specified Error Codes": "✅ Salvo: troca de conta direta em códigos de erro especificados", "✅ Saved: {label}": "✅ Salvo: {label}", "✅ Saved: {label} {value}": "✅ Salvo: {label} {value}", "✅ Settings saved, the app is restarting…": "✅ Configurações salvas; o aplicativo está reiniciando…", "✅ Uploaded to the cloud ({size})": "✅ Enviado para a nuvem ({size})", "✅ models.dev model metadata enabled": "✅ Metadados de modelos do models.dev ativados" });
